(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c42"]=[{"id":"00012867","register_sub_id":"101","register_pk":"367977","name":"臣屋阿部家住宅主屋","kana":"しんやあべけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県石巻市田代浜字仁斗田28","lat":38.2933,"lng":141.42421667,"geo_status":"db","era":"明治14年／昭和25年増築","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積178㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"04 － 0175","desc":"田代島南部の高台に建つ民家。敷地中央に南面する入母屋造平屋建で、正面に玄関と応接室を突出する。東を土間、西を食違い二列四室とし、表側下手を仏壇・神棚を備えた十五畳のおかみ、奥側上手を座敷とする。石巻湾の島嶼集落の歴史的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012867"},{"id":"00006260","register_sub_id":"101","register_pk":"107244","name":"菅原延家住宅板倉","kana":"すがわらえんけじゅうたくいたぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県気仙沼市早稲谷112他","lat":38.94628953,"lng":141.53094193,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"04 － 0065","desc":"桁行８．２ｍ梁間４．６ｍ、木造平屋建、切妻造妻入瓦葺。外壁は１尺毎に柱を立てて竪板を落とし込む堅牢な造りとする。出入口には絵様繰形を施した持送りと二重の腕木で大きな庇を差し掛け、上方に鉄格子を設けた小窓を開く。深い螻羽の重厚な外観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006260"},{"id":"00006682","register_sub_id":"101","register_pk":"107665","name":"菅原文浩家住宅板倉","kana":"すがわらふみひろけじゅうたくいたぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県気仙沼市塚沢67","lat":38.95354827,"lng":141.5208474,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造2階建、瓦葺、建築面積33㎡","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"04 － 0066","desc":"敷地西隅の小高い平地に建つ。桁行８．２ｍ梁間４．６ｍ、木造２階建、切妻造妻入瓦葺。屋根は置屋根で、外壁は１尺毎に柱を建て竪板を落とし込む。平三斗を入れ先端を木鼻風とする二重の腕木と、絵様繰形を施した持送りで作る正面庇の意匠が目を引く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006682"},{"id":"00006727","register_sub_id":"101","register_pk":"107710","name":"鈴木家住宅板倉","kana":"すずきけじゅうたくいたぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県気仙沼市長磯浜98-2","lat":38.83691325,"lng":141.58802291,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造2階建、瓦葺、建築面積33㎡","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"04 － 0069","desc":"桁行８．６ｍ梁間４．８ｍ、木造２階建、切妻造瓦葺。外壁は柱を密に建てて竪板を落とし込み、屋根は置屋根とする。持送りや破風板には絵様を施し、置屋根と桁との間は幾何学文様の彫刻板で埋める。重厚な外観とし、細部を丁寧に仕上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006727"},{"id":"00002586","register_sub_id":"101","register_pk":"103576","name":"農家民宿おりざの森（旧高野家住宅主屋）","kana":"のうかみんしゅくおりざのもり（きゅうたかのけじゅうたくしゅおく）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県加美郡加美町字中嶋南田一番16-1、18-2","lat":38.56751329,"lng":140.82336515,"geo_status":"db","era":"明治23／平成13移築","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積150㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"04 － 0042","desc":"旧高野家はもと福島県境に近い角田市高倉にあった農家で，棟札より明治２３年の建築と判る。近年，移築され，民宿として活用されている。右面切妻造，左面寄棟造，２階建・平入で，全体に立ちが高く，正面２階の内縁など，当地方の養蚕農家の特徴を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002586"},{"id":"00006683","register_sub_id":"101","register_pk":"107666","name":"平田家住宅板倉","kana":"ひらたけじゅうたくいたぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県気仙沼市長磯浜72-1","lat":38.83733766,"lng":141.58877729,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積25㎡","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"04 － 0068","desc":"気仙沼湾を眺望する位置に建つ。桁行６．１ｍ梁間４．２ｍ、木造２階建、切妻造瓦葺。平入で西面中央に庇付の出入口を設け、外側を板戸両開、内側を引戸とする。外壁は１尺毎に柱を建て竪板を落とし込む。比較的簡素で落ち着いた外観が景観に融け込む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006683"},{"id":"00010546","register_sub_id":"101","register_pk":"201120","name":"松谷家住宅岩蔵","kana":"まつやけじゅうたくいわぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県大崎市古川七日町15-1","lat":38.577325,"lng":140.956134,"geo_status":"db","era":"明治後期／昭和37年・平成26年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"石造2階建、鋼板葺、建築面積37㎡","structure_material":"石造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"04－0108","desc":"北側道路に接道して建つ石造二階建の倉庫。敷地形状にあわせた不等辺四角形の平面を持ち、変形寄棟の屋根を架ける。砂岩系とみられる石材を江戸切仕上げとして布積みし、隅部に柱形を表す。壁頂部に廻らすコーニスやアーチ積の楣など装飾的に仕上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010546"},{"id":"00010549","register_sub_id":"101","register_pk":"201123","name":"松谷家住宅御成門","kana":"まつやけじゅうたくおなりもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県大崎市古川七日町15-1","lat":38.576858,"lng":140.956105,"geo_status":"db","era":"明治前期／昭和33年移築・昭和後期改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、銅板葺、間口1.8m","structure_material":"木造","registered":"2015.08.04(平成27.08.04)","register_no":"04－0111","desc":"主屋玄関の正面南方に位置し、表門の奥寄りに位置し、主屋に向けて建つ。間口一・八メートル、切妻造の棟門で、もと杉皮葺であったが、現在は銅板葺とする。武家邸宅のような表門と対照的に数寄屋意匠を持つ門で、小振りながら庭と調和した瀟洒な趣を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010549"},{"id":"00010548","register_sub_id":"101","register_pk":"201122","name":"松谷家住宅表門","kana":"まつやけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県大崎市古川七日町15-1","lat":38.576822,"lng":140.956184,"geo_status":"db","era":"明治前期／昭和33年移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、銅板葺、間口2.4m","structure_material":"木造","registered":"2015.08.04(平成27.08.04)","register_no":"04－0110","desc":"敷地南東隅に位置し、東の街道へ向けて開く。間口二・四メートルを測るやや大型の棟門で、男梁を女梁の代わりに大振りの持送で受け、絵様を入れる。懸魚は左右非対称の波紋様とし、菊紋の六葉を打つ。ケヤキを用い、商家の表門として風格のある構えを示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010548"},{"id":"00010544","register_sub_id":"101","register_pk":"201118","name":"松谷家住宅砂糖蔵","kana":"まつやけじゅうたくさとうぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県大崎市古川七日町15-1","lat":38.577034,"lng":140.956088,"geo_status":"db","era":"明治前期／平成26年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、鋼板葺、建築面積57㎡","structure_material":"土蔵造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"04－0106","desc":"敷地の西辺、大豆蔵の南隣に南北棟で建ち、商品の砂糖を納めていた。置屋根形式の土蔵造二階建で、東正面には彫刻を施した腕木を出して庇を受ける。東面に戸口を設け、二階に木瓜形の窓二所を穿つ。桁行一二メートルと長大な蔵で、当家の繁栄を偲ばせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010544"},{"id":"00010542","register_sub_id":"101","register_pk":"201116","name":"松谷家住宅主屋","kana":"まつやけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県大崎市古川七日町15-1","lat":38.57695,"lng":140.956134,"geo_status":"db","era":"明治前期／明治後期改修・昭和33年移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、銅板葺、建築面積115㎡","structure_material":"木造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"04－0104","desc":"敷地中央に南面する。内法の高い二室続きの座敷部とチャノマからなり、縁を廻らす。明治天皇巡幸時に宮家等の宿泊に数次供され、特に座敷部ではその際と思われる質の高い改修がみられる。雨戸の戸袋上部には繊細な組物を設けるなど、細部装飾にも見所がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010542"},{"id":"00010545","register_sub_id":"101","register_pk":"201119","name":"松谷家住宅大豆蔵","kana":"まつやけじゅうたくだいずぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県大崎市古川七日町15-1","lat":38.577066,"lng":140.956083,"geo_status":"db","era":"明治中期／昭和53年・平成26年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、鋼板葺、建築面積41㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"04－0107","desc":"当家で商った豆類の商品倉庫。敷地の西辺、砂糖蔵の北隣に南北棟で建つ。外壁は、林立する柱の間に白漆喰を塗込めて縦格子のようなコントラストを生み出し、妻壁では重層する梁と束を意匠的に見せ、印象的な外観となる。付庇の絵様付腕木と持送の構成も秀逸。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010545"},{"id":"00010543","register_sub_id":"101","register_pk":"201117","name":"松谷家住宅文庫蔵","kana":"まつやけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"宮城県","address":"宮城県大崎市古川七日町15-1","lat":38.577024,"lng":140.956254,"geo_status":"db","era":"江戸末期／明治後期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、銅板葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"04－0105","desc":"主屋の北東方に南面して建つ、生活用品等を納める蔵。置屋根形式の土蔵造二階建で、軸部をクリで作る。外壁の漆喰塗は、鉢巻や窓上部を黒漆喰塗として強調するほか、鉢巻端部に描く渦紋など、要所に鏝絵を施して装飾的に仕上げ、高い左官技術を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010543"},{"id":"00010547","register_sub_id":"101","register_pk":"201121","name":"松谷家住宅明神社","kana":"まつやけじゅうたくみょうじんしゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"宮城県","address":"宮城県大崎市古川七日町15-1","lat":38.576937,"lng":140.956079,"geo_status":"db","era":"明治前期／昭和33年移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、こけら葺、建築面積0.2㎡、覆屋付","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"04－0109","desc":"敷地西南隅に東面して鞘堂の中に建つ。もとは文庫蔵の東にあったという。こけら葺の一間社流造社殿で、庇部の海老虹梁の透彫木鼻や波紋状の蟇股など、細やかな技巧を凝らし、豊かな装飾を施す。小規模ながら、千木、勝男木を載せて、本格的なつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010547"},{"id":"00002578","register_sub_id":"101","register_pk":"103568","name":"門間箪笥店板倉","kana":"もんまたんすてんいたぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市若林区南鍛冶町143","lat":38.24763904,"lng":140.88872514,"geo_status":"db","era":"昭和10代","year":1935,"year_source":"converted","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積5.8㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"04 － 0034","desc":"主屋と敷地奥の塗り工房の間にあり，荷物等を収蔵している。切妻造・桟瓦葺，妻入で，側廻りに柱を密に立てて貫で繋ぎ，内側に横板を立て込み，戸口には欅の引戸を用いる。桁行２．７５ｍと規模は小さいが，北国に多く見られる形式の倉である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002578"},{"id":"00002579","register_sub_id":"101","register_pk":"103569","name":"門間箪笥店稲荷社","kana":"もんまたんすてんいなりしゃ","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市若林区南鍛冶町143","lat":38.24769762,"lng":140.88874966,"geo_status":"db","era":"昭和10代","year":1935,"year_source":"converted","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積0.77㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"04 － 0035","desc":"主屋と板倉に挟まれた空間にあり，切石積の基壇上に東面して建つ切妻造覆屋内に収まっている。一間社流造で，屋根はこけら葺とする。三斗組の組物，三方に廻した縁，正面の浜床，虹梁・大瓶束架構の妻飾など，小規模だが本式の構造細部を備えた社殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002579"},{"id":"00005225","register_sub_id":"101","register_pk":"106213","name":"遊佐家住宅板蔵","kana":"ゆさけじゅうたくいたぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県登米市中田町石森二木121","lat":38.728774,"lng":141.21984769,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、鉄板葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"04 － 0059","desc":"広間の南から渡廊下で接続する。桁行３間，梁間２間規模で，米蔵として用いられた。屋根は切妻造の鉄板葺である。柱を１尺５寸間隔と密に立て，柱の間に横板を落とし込んで外壁としている。北妻面の戸口は板戸と網戸を片引とする。屋敷構えの一要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005225"},{"id":"00000926","register_sub_id":"101","register_pk":"101916","name":"遊佐家住宅板倉","kana":"ゆさけじゅうたくいたぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県大崎市鳴子温泉字馬場102","lat":38.73740705,"lng":140.74501637,"geo_status":"db","era":"明治18","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造二階建，鉄板葺，建築面積33㎡","structure_material":"木造二階建","registered":"1998.12.11(平成10.12.11)","register_no":"04 － 0006","desc":"敷地の東側にある切妻造，鉄板葺の小規模な板倉で，西面に庇が付く。側壁は，１尺２寸５分毎に柱を立て貫を多用する板壁になる。屋根は，もと小羽葺で棟押さえに切り石を置いたという。棟札から明治１８年の建設でこの地方に共通する板倉の形態をよく保つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000926"},{"id":"00005226","register_sub_id":"101","register_pk":"106214","name":"遊佐家住宅馬屋","kana":"ゆさけじゅうたくうまや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"宮城県","address":"宮城県登米市中田町石森二木121","lat":38.72883806,"lng":141.22040202,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積66㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"04 － 0060","desc":"主屋の北東に位置する。桁行６間半，梁間３間半規模で，南正面１間通りを吹放ちとする。屋根は寄棟造の茅葺で鉄板を被せている。軒は四周をせがい造とする。内部は３室に間仕切り，東から２室を馬屋，西端室を物置とした。外壁は真壁造で白漆喰塗とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005226"},{"id":"00000929","register_sub_id":"101","register_pk":"101919","name":"遊佐家住宅材料小屋","kana":"ゆさけじゅうたくざいりょうごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"宮城県","address":"宮城県大崎市鳴子温泉字馬場102","lat":38.73733351,"lng":140.74447273,"geo_status":"db","era":"昭和20頃","year":1945,"year_source":"db","year_min":1945,"year_max":1945,"year_label":null,"structure":"木造平屋建，鉄板葺，建築面積14㎡","structure_material":"木造平屋建","registered":"1998.12.11(平成10.12.11)","register_no":"04 － 0009","desc":"味噌部屋の南側に並列して建つ切妻造，鉄板葺の小建物で，南側の一間は吹き放ちとし他は板壁とする。名称の通り建築資材や薪等を納める小屋で，味噌部屋と同じく小屋組は簡単な構造になる。素朴な外観の建屋で，生活の一端を知ることのできる要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000929"},{"id":"00005222","register_sub_id":"101","register_pk":"106210","name":"遊佐家住宅主屋","kana":"ゆさけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"宮城県","address":"宮城県登米市中田町石森二木121","lat":38.72891472,"lng":141.22025317,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、鉄板葺、建築面積175㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"04 － 0056","desc":"東下りの敷地の北西部に東面して建つ。桁行９間，梁間４間の木造平屋建である。屋根は寄棟造の鋼板葺とする。南側を床上の居室とし，喰違い四間取とする。土間の上部には棟通りの牛梁から下屋柱に向かって掛け渡した曲がりの大きな梁が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005222"},{"id":"00000376","register_sub_id":"101","register_pk":"101366","name":"遊佐家住宅主屋","kana":"ゆさけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"宮城県","address":"宮城県大崎市鳴子温泉字要害90-1","lat":38.73210343,"lng":140.75315337,"geo_status":"db","era":"19世紀中頃","year":1850,"year_source":"estimated","year_min":1831,"year_max":1870,"year_label":"19世紀中頃","structure":"木造平屋建，鉄板葺，建築面積226㎡","structure_material":"木造平屋建","registered":"1997.12.12(平成9.12.12)","register_no":"04 － 0002","desc":"古来から名馬の産地として知られる当地方の古式の農家は，土間を広くとり厩を取り込むのが一般的である。遊佐家住宅は，大型の寄棟造の主屋で，こうした平面を保つ農家の好例である。近年，内部を中心に改修を行ったが，外観や軸組はよく保存されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000376"},{"id":"00000925","register_sub_id":"101","register_pk":"101915","name":"遊佐家住宅主屋","kana":"ゆさけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県大崎市鳴子温泉字馬場102","lat":38.73744119,"lng":140.74469859,"geo_status":"db","era":"明治10代","year":1877,"year_source":"converted","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積207㎡","structure_material":"木造平屋建","registered":"1998.12.11(平成10.12.11)","register_no":"04 － 0005","desc":"伝統的な四間取，内厩式の平面を保つ大型の農家で，広い土間と厩の存在はかつて馬の産地であったこの地方の民家に共通する特色である。もと寄棟造，茅葺であったが，近年入母屋造，銅板葺に変更し，伝統的な間取を踏襲しつつ，厩や水廻りも巧みに改修した。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000925"},{"id":"00000927","register_sub_id":"101","register_pk":"101917","name":"遊佐家住宅外風呂","kana":"ゆさけじゅうたくそとぶろ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"宮城県","address":"宮城県大崎市鳴子温泉字馬場102","lat":38.73742281,"lng":140.74486405,"geo_status":"db","era":"昭和11頃","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"コンクリート造風呂、面積2.5㎡、深さ0.6m、木造上屋付属","structure_material":"コンクリート造風呂","registered":"1998.12.11(平成10.12.11)","register_no":"04 － 0007","desc":"主屋の東面にある小規模の切妻造，平入，鉄板葺の温泉施設で，背面側に洗濯場とする庇が付く。コンクリート製の湯舟を中心に洗い場，脱衣場を覆った簡素な建屋で，小屋組を見せる。素朴な佇まいの施設であるが，地域の共同温泉として今も利用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000927"},{"id":"00005224","register_sub_id":"101","register_pk":"106212","name":"遊佐家住宅土蔵","kana":"ゆさけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県登米市中田町石森二木121","lat":38.72869166,"lng":141.22000708,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、スレート葺、建築面積22㎡","structure_material":"土蔵造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"04 － 0058","desc":"広間の東側に建つ，桁行３間，梁間２間規模の土蔵造２階建で，切妻造の置屋根を天然スレート葺とする。外壁は白漆喰塗で，腰を海鼠壁とする。北妻面に戸口を設けて片引きの土戸，板戸，網戸を建て込み，スレート葺庇を付ける。妻面２階には窓を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005224"},{"id":"00005223","register_sub_id":"101","register_pk":"106211","name":"遊佐家住宅広間","kana":"ゆさけじゅうたくひろま","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"宮城県","address":"宮城県登米市中田町石森二木121","lat":38.72883238,"lng":141.22004946,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積65㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"04 － 0057","desc":"敷地の西側，主屋の南に並ぶ，桁行５間，梁間３間半の木造平屋建で，三方に縁を巡らす。屋根は寄棟造で茅葺の上に鉄板を被せる。四周の軒をせがい造とする。内部は１０畳２室で，南上手の座敷に床・棚・附書院，北下手の座敷に床・棚を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005223"},{"id":"00005227","register_sub_id":"101","register_pk":"106215","name":"遊佐家住宅味噌蔵","kana":"ゆさけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県登米市中田町石森二木121","lat":38.72898635,"lng":141.22036468,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造平屋建、鉄板葺、建築面積14㎡","structure_material":"土蔵造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"04 － 0061","desc":"主屋北西の一段高い土地に位置する。桁行２間半，梁間２間規模の土蔵造平屋建である。屋根は切妻造，鉄板葺の置屋根とする。外壁は白漆喰塗で，腰をモルタル塗洗出しとする。東正面に戸口を設けて，土戸と板戸を片引きに建て込む。屋敷構えの一要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005227"},{"id":"00000928","register_sub_id":"101","register_pk":"101918","name":"遊佐家住宅味噌部屋","kana":"ゆさけじゅうたくみそべや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"宮城県","address":"宮城県大崎市鳴子温泉字馬場102","lat":38.73737816,"lng":140.74448323,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建，瓦葺，建築面積10㎡","structure_material":"木造平屋建","registered":"1998.12.11(平成10.12.11)","register_no":"04 － 0008","desc":"主屋の西側に位置し，大壁造とする小規模な切妻造，平入，桟瓦葺の建屋。妻側は簡単な和小屋組とするが，中央部は梁行の柱筋に湾曲した梁材を渡し母屋桁を載せただけの構造になる。屋敷構えを構成する要素で，遺存例が比較的少なく貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000928"},{"id":"00000930","register_sub_id":"101","register_pk":"101920","name":"遊佐家住宅室","kana":"ゆさけじゅうたくむろ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"昭和前","pref":"宮城県","address":"宮城県大崎市鳴子温泉字馬場102","lat":38.73734139,"lng":140.74455677,"geo_status":"db","era":"昭和10頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"石造貯蔵庫，建築面積5.４㎡","structure_material":"石造貯蔵庫","registered":"1998.12.11(平成10.12.11)","register_no":"04 － 0010","desc":"材料小屋の東側の段差を利用して造られた横穴式の石室で，側壁は切石積とし，アーチ型をしたコンクリート屋根を設けて造る。現在も主に漬物野菜の貯蔵用に使われている。正面の扉は欠失し開放となっているが，戦前期の農村生活を知る上で貴重な室である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000930"},{"id":"00014996","register_sub_id":"101","register_pk":"529274","name":"横田家住宅板倉","kana":"よこたけじゅうたくいたくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県仙台市宮城野区鶴巻一丁目1008-5","lat":38.26420278,"lng":140.96602778,"geo_status":"db","era":"明治13年／昭和53年改修、平成8年移築","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造二階建、鉄板葺、建築面積20㎡","structure_material":"木造二階建","registered":"2024.08.15(令和6.08.15)","register_no":"04 - 0220","desc":"仙台市東部に位置する農家の道具蔵兼籾蔵。敷地に西面して建つ二階建切妻造平入鉄板葺。側柱の間に横板を落とし込んで外壁とし、西面南寄りを戸口とする。内部は各階板敷で、１階南側を仕切り籾の貯蔵場とする。小規模ながら丁寧なつくりで当地域特有の板蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014996"},{"id":"00004499","register_sub_id":"101","register_pk":"105489","name":"赤川家住宅蔵","kana":"あかがわけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市大森町字大森176-2","lat":39.3451646,"lng":140.42874619,"geo_status":"db","era":"明治18／明治後期改造","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積67㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"05 － 0118","desc":"桁行６間梁間３間，切妻造，鉄板葺の２階建土蔵で，後に外壁に煉瓦を積む。創建時の棟梁は大沼冨吉。切石基礎上に建ち，軒の鉢巻は漆喰塗とし，鉢巻下端と胴蛇腹に煉瓦の歯飾りを廻す。北面に黒漆喰塗の戸口があり，南面にも煉瓦で額縁を飾った戸口を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004499"},{"id":"00003343","register_sub_id":"101","register_pk":"104333","name":"秋田県ゆとり生活創造センター昭和館（旧佐藤家住宅）主屋","kana":"あきたけんゆとりせいかつそうぞうせんたーしょうわかん（きゅうさとうけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県秋田市上北手荒巻字堺切24-2","lat":39.68789372,"lng":140.14949886,"geo_status":"db","era":"昭和10／平成13移築","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、銅板葺、建築面積254㎡、正面玄関ポーチ付","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"05 － 0090","desc":"大曲市内にあった邸宅を移築し，集会施設として再生。木造２階建で，長い廊下によって客間，居間など多数の部屋を繋ぐ。各室とも良材を用い瀟洒な数寄屋風意匠になり，凝った細工の建具を多用する。大小の破風を重ねた立ちの高い外観は通りに面し異彩を放つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003343"},{"id":"00003344","register_sub_id":"101","register_pk":"104334","name":"秋田県ゆとり生活創造センター昭和館（旧佐藤家住宅）土蔵","kana":"あきたけんゆとりせいかつそうぞうせんたーしょうわかん（きゅうさとうけじゅうたく）どぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県秋田市上北手荒巻字堺切24-2","lat":39.68795166,"lng":140.14933562,"geo_status":"db","era":"昭和10／平成13移築","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"土蔵造2階建、鋼板葺、建築面積78㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"05 － 0091","desc":"主屋背後に建つ２階建の土蔵。大小２棟を桁行きに接続させ，屋根も一部落棟となるが，内部は１，２階とも開口部を設け連続する。良材を用い半間毎に柱，床梁を入れた堅牢なつくりで，漆喰塗で腰を簓子下見とする外部は，開口部回りや軒蛇腹を黒漆喰塗で飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003344"},{"id":"00001546","register_sub_id":"101","register_pk":"102536","name":"秋田県立農業科学館曲屋（旧伊藤家住宅）","kana":"あきたけんりつのうぎょうかがくかんまがりや（きゅういとうけじゅうたく）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県大仙市内小友字中沢171-4","lat":39.43499,"lng":140.440094,"geo_status":"db","era":"明治33～36／平成1移築","year":1900,"year_source":"converted","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造平屋建、茅葺、建築面積218㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"05 － 0056","desc":"田沢湖町の伊藤家より農業科学館展示用として寄贈された。茅葺，土台建の曲り屋民家で，平成元年に移築され，当初形式に復原された。良質の部材を吟味して用い，丁寧なつくりになる。馬屋のとり方や出入口の位置に地域性が認められ，正面縁の半蔀は珍しい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001546"},{"id":"00005408","register_sub_id":"101","register_pk":"106396","name":"阿部家住宅小屋","kana":"あべけじゅうたくこや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県雄勝郡羽後町田代字尼沢140","lat":39.20512681,"lng":140.33211288,"geo_status":"db","era":"明治28","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造平屋建、茅葺、建築面積87㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"05 － 0142","desc":"土蔵の東北方に位置し，主屋や土蔵とは棟を４５度振って建つ。桁行６間，梁間４間規模の木造平屋建で，農機具や資材等の物置場で，内部は２室に分け，南妻面に下屋を付ける。端正な茅葺の切妻屋根を架け，妻に破風板を付け，棟にクラガケを載せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005408"},{"id":"00005406","register_sub_id":"101","register_pk":"106394","name":"阿部家住宅主屋","kana":"あべけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県雄勝郡羽後町田代字尼沢140","lat":39.20483514,"lng":140.33223014,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、鉄板葺、建築面積240㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"05 － 0140","desc":"中世城趾と推測される小山東麓の屋敷地中央に東面して建つ。桁行１０間半，梁行５間半規模，寄棟造，鉄板葺の平屋建主体部の正面に桁行６間の中門を突き出す。主体部は南を土間，北を床上部とする。内法上の小壁のたちが高いのが特色で，２段の貫を通す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005406"},{"id":"00005407","register_sub_id":"101","register_pk":"106395","name":"阿部家住宅土蔵","kana":"あべけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県雄勝郡羽後町田代字尼沢140","lat":39.204953,"lng":140.33204295,"geo_status":"db","era":"明治26","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積123㎡","structure_material":"土蔵造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"05 － 0141","desc":"主屋の北西方に位置する。南北棟で建ち，切妻造，鉄板葺の木造鞘内に収まる。桁行６間，梁間４間規模の２階建土蔵で，南妻面に戸口を設ける。外壁は漆喰塗で，戸口の観音開の扉は掛子塗とし，まぐさ位置に鏝絵を付けるなど丁寧なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005407"},{"id":"00001030","register_sub_id":"101","register_pk":"102020","name":"泉川家住宅","kana":"いずみかわけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県横手市大水戸町5-8","lat":39.31550098,"lng":140.56244579,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建，鉄板葺，建築面積140㎡","structure_material":"木造平屋建","registered":"1999.02.17(平成11.02.17)","register_no":"05 － 0043","desc":"横手市街中央部に建つ民家風住宅。正面西寄りに懸魚付ムクリ破風の玄関を構える。間取りはチャノマ等をＬ字型に配し，東側に客座敷２室を置き，東妻面に出の深い庇を付ける。客座敷は，数寄屋造で，丸窓や欄間などの凝った意匠に見所がある。棟梁は加藤徳治。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001030"},{"id":"00001029","register_sub_id":"101","register_pk":"102019","name":"伊藤八重郎家住宅","kana":"いとうはちじゅうろうけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"大正","pref":"秋田県","address":"秋田県横手市安本字安本71","lat":39.35620276,"lng":140.53451578,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建，鉄板葺，建築面積261㎡","structure_material":"木造平屋建","registered":"1999.02.17(平成11.02.17)","register_no":"05 － 0042","desc":"横手市街の北方，市境近くに建つ大型農家。正面西寄りに切妻造の玄関を構え，その内部を土縁とする。間取りの基本は広間型３間取りで，東側にムクリ破風の客玄関と客座敷を配し，東側面を土縁とする。近世上層農家の流れを汲む遺構のひとつ。棟梁は伊藤常吉。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001029"},{"id":"00001031","register_sub_id":"101","register_pk":"102021","name":"遠藤家住宅主屋","kana":"えんどうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市上内町1-1","lat":39.31282094,"lng":140.57170074,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造２階建，鉄板葺，建築面積153㎡","structure_material":"木造２階建","registered":"1999.02.17(平成11.02.17)","register_no":"05 － 0044","desc":"横手市街の中央部，藩政期の武家住宅地の一角に建つ。横手川に面して円弧状破風の玄関を構え，玄関土間の奥に台所，左手に２室の客座敷を配し，土間上部の２階に座敷を設ける。客座敷の東方に池泉庭園を造るなど武家住宅の面影を伝えることで貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001031"},{"id":"00001032","register_sub_id":"101","register_pk":"102022","name":"遠藤家住宅土蔵","kana":"えんどうけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市上内町1-1","lat":39.31287414,"lng":140.57184514,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"土蔵造２階建，鉄板葺，建築面積50㎡","structure_material":"土蔵造２階建","registered":"1999.02.17(平成11.02.17)","register_no":"05 － 0045","desc":"主屋の背後に連なる東西棟の２階建土蔵で，外部の腰を煉瓦積とする。蔵前を主屋台所の奥に設け，他の妻面に下屋を付す。製材業を営んだ時代の蔵に相応しく、内部階下の箱階段、床梁、小屋組などに良材がふんだんに使われている。棟梁は高橋政蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001032"},{"id":"00001162","register_sub_id":"101","register_pk":"102152","name":"桜櫓館（旧櫻場家住宅）","kana":"おうろかん（きゅうさくらばけじゅうたく）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"秋田県","address":"秋田県大館市字中城12-2・13-3・22-4","lat":40.271568,"lng":140.565842,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建，鉄板葺一部銅板葺，建築面積232㎡","structure_material":"木造2階建","registered":"1999.07.08(平成11.07.08)","register_no":"05 － 0054","desc":"大館町長を勤めた櫻場文蔵が建てたもので，設計は石田常吉・小野熊蔵，大工棟梁は越後甚吉である。洋室を備えた和風住宅で，塔屋を持ち複雑な屋根をかけた特異な外観をもつ。室内は，杉の良材を用いて仕上げ，建具や付書院に優れた技能が発揮されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001162"},{"id":"00004309","register_sub_id":"101","register_pk":"105299","name":"大井家住宅主屋","kana":"おおいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県由利本荘市矢島町舘町59","lat":39.22922972,"lng":140.13470349,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋一部2階建、鉄板葺、建築面積405㎡","structure_material":"木造平屋一部2階建","registered":"2004.11.08(平成16.11.08)","register_no":"05 － 0112","desc":"街路に北面して建つ。主体部は南北棟の寄棟造で，西側に座敷と納戸，東側通り土間沿いに見世・仏間・帳場を並べ，北西に表玄関，北面東寄りに通用玄関を設け，南側に東西棟の家人用居宅部を配する。棟梁，工費，材料などが判明。当地の指標的住宅のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004309"},{"id":"00002349","register_sub_id":"101","register_pk":"103339","name":"男鹿真山伝承館","kana":"おがしんざんでんしょうかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県男鹿市北浦真山字水喰沢80","lat":39.92838491,"lng":139.76687239,"geo_status":"db","era":"明治40／平成7移築","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、茅葺、建築面積173㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"05 － 0074","desc":"正面ニワ側を前方に突出させ馬屋とするいわゆる中門造の民家。屋根は寄棟造，茅葺で，高窓を開けた中門正面大戸口上は軒を切り上げる。もと近郊の目黒家住宅主屋として建築され，平成７年現在地に移築，民俗資料等を展示しつつ公開活用がはかられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002349"},{"id":"00004097","register_sub_id":"101","register_pk":"105087","name":"菊地家住宅座敷","kana":"きくちけじゅうたくざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"秋田県","address":"秋田県南秋田郡五城目町字鵜ノ木88-1","lat":39.94309255,"lng":140.11720646,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、鋼板葺、建築面積117㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"05 － 0099","desc":"敷地の北方居住部の東寄りに位置し，東西棟で建つ。桁行５間梁間５間半規模，入母屋造，鉄板葺の平屋建で，西北２面に土縁庇を廻し，内部は１２畳半の座敷などを田の字型に配置する。吟味された木材を用いた全体に上質なつくりの書院座敷で，棟梁は村上幸吉。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004097"},{"id":"00004098","register_sub_id":"101","register_pk":"105088","name":"菊地家住宅離れ","kana":"きくちけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県南秋田郡五城目町字鵜ノ木88-1","lat":39.94324732,"lng":140.11704719,"geo_status":"db","era":"昭和10頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、鋼板葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"05 － 0100","desc":"座敷の北西方に庭園を介して東西棟で建つ。桁行３間梁間２間規模の入母屋造，鉄板葺，平屋建で，庭園に面した東南２面に土縁庇を廻すなど座敷と似た構成をとる。内部は１０畳半の座敷で，床柱に南洋材を用いるなど凝った造作が随所に見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004098"},{"id":"00004099","register_sub_id":"101","register_pk":"105089","name":"菊地家住宅文庫蔵","kana":"きくちけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県南秋田郡五城目町字鵜ノ木88-1","lat":39.94320441,"lng":140.11689642,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建及び木造平屋建、鋼板葺、建築面積132㎡","structure_material":"土蔵造2階建及び木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"05 － 0101","desc":"離れの西南に接して東西棟で建つ。桁行４間半梁間３間規模，切妻造，鉄板葺の２階建妻入土蔵で，東面に下屋を差し掛けて蔵前をとり，西方に便所・風呂場を付属する。正面は黒漆喰塗で，戸前周囲は唐草模様を施すなど高度で繊細な左官技法で仕上げている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004099"},{"id":"00013490","register_sub_id":"101","register_pk":"504589","name":"季子家住宅内蔵","kana":"きしけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市増田町吉野字村ノ後58","lat":39.20105,"lng":140.59093056,"geo_status":"db","era":"明治後期／昭和44年頃改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、板葺（鉄板仮葺）、建築面積85㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"05 － 0231","desc":"主屋の北西に接続して南北棟で建つ内蔵で、鞘に収まる。桁行五間、梁間四間の土蔵造二階建妻入、外壁は漆喰で塗籠める。一階は板間と畳敷のもと座敷で、二階は板間の一室である。四段掛子塗の土扉や漆塗の鞘飾りは見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013490"},{"id":"00013489","register_sub_id":"101","register_pk":"504588","name":"季子家住宅主屋","kana":"きしけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市増田町吉野字村ノ後58","lat":39.20104722,"lng":140.59096667,"geo_status":"db","era":"明治後期／昭和50年頃改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、茅葺（鉄板仮葺）、建築面積191㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"05 － 0230","desc":"旧増田町の吉野集落中央に南面して建つ。木造一部二階建、寄棟造金属板葺で軒桁を三段に重ねる。桁行七間、梁間四間で三方に下屋を廻し、南面西寄りに切妻玄関を張出す。床上部は食違四間取で南面の居室に採光の為の高窓を設ける。地域に残る大規模農家主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013489"},{"id":"00013491","register_sub_id":"101","register_pk":"504590","name":"季子家住宅外蔵","kana":"きしけじゅうたくそとぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市増田町吉野字村ノ後58","lat":39.20090833,"lng":140.590925,"geo_status":"db","era":"明治後期／昭和44年頃改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、板葺（鉄板仮葺）、建築面積122㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"05 － 0232","desc":"主屋の南西に矩折れに接続し、若干角度を振って建つ。桁行五間、梁間三間半の土蔵造二階建の南北棟の切妻造である。農業用の倉庫で南に戸口を開く。外壁は漆喰で塗籠められ、鋼板葺、板張の鞘に収まる。小屋組は豪放な重ね梁形式で見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013491"},{"id":"00016477","register_sub_id":"101","register_pk":"574839","name":"旧薄葉家住宅主屋","kana":"きゅううすばけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市羽黒町52","lat":39.31657194,"lng":140.56929778,"geo_status":"db","era":"明治前期／昭和18年頃増築、令和6年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、鋼板葺、建築面積114㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"05 - 0260","desc":"旧横手城下の南西部、旧武家町に位置する住宅の主屋。平屋建切妻造鉄板葺で、外壁は漆喰塗、腰は下見板張とする。南庭に面して二室の座敷を配するなど、当地の武家住宅の平面形式を踏襲する。天井高く、採光のための高窓など雪国らしい近代和風住宅の主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016477"},{"id":"00014715","register_sub_id":"101","register_pk":"518973","name":"旧大潟村入植予定者観覧用農家住宅","kana":"きゅうおおがたむらにゅうしょくよていしゃかんらんようのうかじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"昭和後","pref":"秋田県","address":"秋田県南秋田郡大潟村字東二丁目1-6","lat":40.01733056,"lng":139.96168056,"geo_status":"db","era":"昭和44年","year":1969,"year_source":"db","year_min":1969,"year_max":1969,"year_label":null,"structure":"コンクリートブロック造及び木造2階建、鉄板葺、建築面積58㎡","structure_material":"コンクリートブロック造及び木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"05 - 0245","desc":"大潟村中心部に位置する入植予定者の観覧用に建てた住宅。コンクリートブロック造及び木造二階建鉄板葺の南北棟で外壁はモルタル塗仕上とする。妻入で北中央を玄関とし、一階に三室、二階に二室を配する。大きな三角屋根が八郎潟干拓地の特徴的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014715"},{"id":"00014714","register_sub_id":"101","register_pk":"518972","name":"旧片野家住宅表門及び塀","kana":"きゅうかたのけじゅうたくおもてもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市羽黒町65","lat":39.31369167,"lng":140.57248333,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"門 木造、鉄板葺、間口4.5m 塀 土塀、総延長126m","structure_material":"門 木造","registered":"2024.03.06(令和6.03.06)","register_no":"05 - 0244","desc":"表門は敷地東面に通りより引込んで建つ一間一戸薬医門鉄板葺で、軒は緩く反りを付けた一軒疎垂木、両妻は蟇股や懸魚を彫刻で飾る。門両脇に腰を簓戸下見板張とした鉄板葺土塀が続き、敷地の東、南、西面を画す。表門と連なる長大な塀が旧家の表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014714"},{"id":"00014710","register_sub_id":"101","register_pk":"518968","name":"旧片野家住宅主屋","kana":"きゅうかたのけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市羽黒町65","lat":39.31356944,"lng":140.57220278,"geo_status":"db","era":"明治中期／昭和前期改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋一部2階建、鉄板葺、建築面積327㎡","structure_material":"木造平屋一部2階建","registered":"2024.03.06(令和6.03.06)","register_no":"05 - 0240","desc":"横手城跡南方の旧武家町に所在する旧家の主屋。平屋一部二階建の鉄板葺で、中庭を中心に玄関応接棟、座敷棟、大広間棟、北廊下を配した大規模なもの。玄関応接棟には唐破風造の玄関を構え、座敷棟や大広間棟には良材を用いた座敷を備えた上質な近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014710"},{"id":"00014712","register_sub_id":"101","register_pk":"518970","name":"旧片野家住宅中の蔵","kana":"きゅうかたのけじゅうたくなかのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市羽黒町65","lat":39.31355833,"lng":140.57195833,"geo_status":"db","era":"明治38年頃／昭和30年頃改修","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積108㎡","structure_material":"土蔵造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"05 - 0242","desc":"主屋の北西に接続し、かつて文書類を収納した蔵。二階建切妻造東西棟で、置屋根形式の鉄板葺とし、東に蔵前を接続する。側廻りに柱を密に配し、各階板敷とし、小屋組は二重の梁で棟木と母屋桁を受ける。外壁は漆喰仕上で上部に鉢巻を廻し重厚な外観の中の倉。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014712"},{"id":"00014713","register_sub_id":"101","register_pk":"518971","name":"旧片野家住宅味噌蔵","kana":"きゅうかたのけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市羽黒町65","lat":39.31374722,"lng":140.57206944,"geo_status":"db","era":"明治22年","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積137㎡","structure_material":"土蔵造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"05 - 0243","desc":"主屋の北に接続する味噌醸造用の蔵。土蔵造二階建切妻造鉄板葺の南北棟で、外壁は中塗仕上の大壁とし、南に切妻造妻入鉄板葺の落棟を接続し作業場とする。内部一階は一室の石敷で醸造場、二階は一室の板敷で物置とする。規模大きく旧家の様相を示す味噌蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014713"},{"id":"00014711","register_sub_id":"101","register_pk":"518969","name":"旧片野家住宅煉瓦蔵","kana":"きゅうかたのけじゅうたくれんがぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市羽黒町65","lat":39.31348333,"lng":140.57205833,"geo_status":"db","era":"明治38年","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"煉瓦造2階建、鉄板葺、建築面積99㎡","structure_material":"煉瓦造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"05 - 0241","desc":"主屋の南西に接続する家財蔵。煉瓦造二階建切妻造鉄板葺の東西棟。東を戸口として掛子塗扉を開き、各階は１室の板敷で内部中央に独立柱を立てる。二階上部は太い梁を重ねた豪壮な小屋組を現す。内部の柱や梁は透漆塗で艶やかに仕上げた豪華なつくりの煉瓦蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014711"},{"id":"00008412","register_sub_id":"101","register_pk":"134808","name":"旧対川荘","kana":"きゅうたいせんそう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県雄勝郡羽後町西馬音内字川原田12-2","lat":39.20041516,"lng":140.40879775,"geo_status":"db","era":"明治後期／平成19年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、鉄板葺、建築面積111㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"05 － 0184","desc":"北流する西馬音内川に西面する敷地に建つ。木造二階建、寄棟造鉄板葺、建築面積一一一平方メートル。一階二階とも眺望のために、ガラス戸を建て開放的な佇まいとし、二階にはトコや棚を構える主座敷と次の間が並び、三方に縁をまわす。軽快な意匠になる庭園建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008412"},{"id":"00005233","register_sub_id":"101","register_pk":"106221","name":"旧奈良家住宅北米蔵","kana":"きゅうならけじゅうたくきたこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県秋田市金足小泉字上前8","lat":39.823666,"lng":140.064941,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造平屋建、鉄板葺、建築面積184㎡","structure_material":"土蔵造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"05 － 0135","desc":"南米蔵の北に南北棟で建つ。桁行８間，梁間３間半の土蔵造で，東正面に２間半幅の下屋がつく。切妻造，鉄板葺の置屋根と下屋の屋根を南米蔵と一連に造る。正面戸口は両開き土戸，背面４箇所の窓は片開戸とする。外壁は白漆喰塗，下屋の壁は竪羽目板張である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005233"},{"id":"00005230","register_sub_id":"101","register_pk":"106218","name":"旧奈良家住宅座敷蔵","kana":"きゅうならけじゅうたくざしきぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県秋田市金足小泉字上前8","lat":39.82348817,"lng":140.06517686,"geo_status":"db","era":"明治23","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"土蔵造2階建、銅板葺、建築面積114㎡","structure_material":"土蔵造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"05 － 0132","desc":"味噌蔵西に東西棟で建つ。桁行７間，梁間３間半の土蔵造２階建，切妻造，銅板葺の置屋根で，両妻面に下屋がつく。外壁は白漆喰塗で腰に切石を張る。東妻面に戸口を設け，下屋が付く。１階は１間幅の前室と広間，２階は２間半幅の前室に８畳座敷と板間とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005230"},{"id":"00005231","register_sub_id":"101","register_pk":"106219","name":"旧奈良家住宅新住居","kana":"きゅうならけじゅうたくしんじゅうきょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県秋田市金足小泉字上前8","lat":39.82323306,"lng":140.06505513,"geo_status":"db","era":"明治28","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造2階建、銅板葺、建築面積152㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"05 － 0133","desc":"主屋の西に東西棟で北面して建つ。木造２階建で，寄棟屋根を銅板葺とする。北面に玄関を突出し，１階に１２畳座敷と８畳，２階に８畳座敷と４畳茶室を配す。廊下を主屋方向に延ばし便所が附属する。外壁は竪羽目板張とする。厨房部は後年の増築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005231"},{"id":"00005229","register_sub_id":"101","register_pk":"106217","name":"旧奈良家住宅文庫蔵","kana":"きゅうならけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県秋田市金足小泉字上前8","lat":39.82307313,"lng":140.06512994,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、銅板葺、建築面積50㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"05 － 0131","desc":"主屋の西に東面して建つ。桁行４間，梁間３間の木造２階建で，外壁はモルタル塗洗出しとする。屋根は寄棟造，銅板葺である。南面東寄りに戸口を設け，両開き鉄扉と片引き格子戸を建て込む。両側面の窓は１階は片開き，２階は上げ下げで外にシャッターが付く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005229"},{"id":"00005228","register_sub_id":"101","register_pk":"106216","name":"旧奈良家住宅味噌蔵","kana":"きゅうならけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県秋田市金足小泉字上前8","lat":39.82341823,"lng":140.06537595,"geo_status":"db","era":"明治7","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"土蔵造平屋建、銅板葺、建築面積88㎡","structure_material":"土蔵造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"05 － 0130","desc":"敷地の北辺東寄り，主屋の北に位置する。桁行５間，梁間３間半の土蔵造平屋建で，南正面に１間半の下屋が付く。屋根は北から２間位置を棟とする招き屋根形の置屋根で銅板葺。外壁は白漆喰塗で，腰を下見板張とする。小屋組には曲がりの強い登り梁を用いる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005228"},{"id":"00005232","register_sub_id":"101","register_pk":"106220","name":"旧奈良家住宅南米蔵","kana":"きゅうならけじゅうたくみなみこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県秋田市金足小泉字上前8","lat":39.82353019,"lng":140.0648489,"geo_status":"db","era":"明治26","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"土蔵造平屋建、鉄板葺、建築面積117㎡","structure_material":"土蔵造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"05 － 0134","desc":"敷地の北西部に位置し，南北棟で桁行５間半，梁間３間半の土蔵造で，東正面に２間半幅の下屋が付く。切妻造の置屋根を鉄板葺として，北米蔵と一連に造る。正面戸口は両開き土戸，南面戸口は引分け板戸とする。背面２箇所に窓を開く。外壁は白漆喰塗である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005232"},{"id":"00011236","register_sub_id":"101","register_pk":"209071","name":"旧本郷家住宅主屋","kana":"きゅうほんごうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県大仙市角間川町字西中上町19","lat":39.405826,"lng":140.480532,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造平屋一部2階建、鉄板葺、建築面積396㎡","structure_material":"木造平屋一部2階建","registered":"2016.11.29(平成28.11.29)","register_no":"05－0212","desc":"横手盆地の中央に位置し、雄物川舟運で栄えた角間川町に位置する。東列に三室の座敷を並べ、中列に仏間と納戸、西列にオエを配し、西から南半に矩折れの通り土間を設けて玄関を開く。天井の高い内部空間を持ち、雪国らしく、土間を広くとって高窓を開ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011236"},{"id":"00011238","register_sub_id":"101","register_pk":"209073","name":"旧本郷家住宅文庫蔵","kana":"きゅうほんごうけじゅうたくぶんこくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県大仙市角間川町字西中上町19","lat":39.40585,"lng":140.48027,"geo_status":"db","era":"明治2","year":1869,"year_source":"db","year_min":1869,"year_max":1869,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積263㎡","structure_material":"土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"05－0214","desc":"主屋の西方に接続して東西棟の鞘部を設け、内部に長大な二階建の土蔵を設ける内蔵の形式を持つ。土蔵部の桁行は一六・四メートルで、東前面に蔵前を付属する。漆で拭った豪壮な柱を立てるなど、当地の内蔵の様相を伝え、年代の明らかな土蔵として価値がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011238"},{"id":"00011239","register_sub_id":"101","register_pk":"209074","name":"旧本郷家住宅味噌蔵","kana":"きゅうほんごうけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県大仙市角間川町字西中上町19-5","lat":39.405995,"lng":140.480331,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積66㎡","structure_material":"土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"05－0215","desc":"主屋の北側に東西棟で独立して建つが、もとは主屋の調理場と接続していた。二階建で置屋根形式とし、外壁は石造風に目地を切ったモルタル洗出仕上としている。ほかに窓の持ち送りに曲線状の意匠を用いるなど、周囲の庭園と一体となって独特の景観を成す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011239"},{"id":"00011237","register_sub_id":"101","register_pk":"209072","name":"旧本郷家住宅洋館","kana":"きゅうほんごうけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"秋田県","address":"秋田県大仙市角間川町字西中上町19","lat":39.405663,"lng":140.4805,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積68㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"05－0213","desc":"主屋の南方に接続して建つ。東西棟の切妻造とし、外壁を黄土色のドイツ壁風仕上げとし、腰に煉瓦タイルを貼って装飾的に仕上げる。妻側には特徴的な出窓を各二所設けて外観にアクセントを付ける。内部は中廊下を介して洋室と和室を二室ずつ並べる平面を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011237"},{"id":"00004903","register_sub_id":"101","register_pk":"105893","name":"國萬歳酒造洋館","kana":"くにばんざいしゅぞうようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"秋田県","address":"秋田県秋田市新屋元町142他","lat":39.68414786,"lng":140.08365138,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、鋼板葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"05 － 0129","desc":"作業場の南側に位置する。桁行４間，梁間２間，木造平屋建で，寄棟造，外壁を下見板張とし，窓枠を段状断面とした縦長窓を外周に配す。軒には凸形の瓔珞飾を廻し，小壁には幾何学的な凹凸を付けた板を帯状に連続させる。小規模ながら丁寧な装飾に見所がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004903"},{"id":"00012687","register_sub_id":"101","register_pk":"367590","name":"顧空庵","kana":"こくうあん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"秋田県","address":"秋田県湯沢市湯ノ原一丁目275-1他","lat":39.16613778,"lng":140.496735,"geo_status":"db","era":"昭和28年／平成19年移築","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積55㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"05 － 222","desc":"市街地東部にある白井晟一設計の住宅。軒が深く緩い切妻屋根の平屋建で、焦茶の柱と漆喰壁が特徴的。東に玄関や台所等、西に四畳半の小上がり付の一室を配し、低い天井に大きな開口を組合わせ、ゆったりした空間をつくる。白井の和風建築の特徴を示す小住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012687"},{"id":"00007604","register_sub_id":"101","register_pk":"108586","name":"小西家住宅主屋","kana":"こにしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県横手市雄物川町薄井字薄井94","lat":39.32465076,"lng":140.43747707,"geo_status":"db","era":"昭和15／昭和20改修","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造2階一部平屋建、鉄板葺、建築面積241㎡","structure_material":"木造2階一部平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"05 － 0157","desc":"敷地の中央に南面して建つ。２階建の東に平屋建の居室を設け、屋根は寄棟造鉄板葺に落棟を付けて葺き降ろす。２階建は１、２階とも東西に３室並べ、南北に縁を通し、西端室を主座敷とし、座敷構えを設ける。黒檀のトコ柱や繊細な付書院など、瀟洒な意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007604"},{"id":"00007605","register_sub_id":"101","register_pk":"108587","name":"小西家住宅文庫蔵","kana":"こにしけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市雄物川町薄井字薄井94","lat":39.324776,"lng":140.43758891,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、鉄板葺、建築面積149㎡","structure_material":"土蔵造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"05 － 0158","desc":"主屋の北面東寄りに接続する妻入土蔵。南北棟の切妻造鉄板葺置屋根とする。桁行１４ｍ梁間７．５ｍ規模の２階建で、東面に通り土間を付設する。主屋側の扉は掛子塗で、黒漆喰の磨仕上げとする。地梁に太い垂木を密に架け渡し、力強い内部空間をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007605"},{"id":"00007606","register_sub_id":"101","register_pk":"108588","name":"小西家住宅座敷蔵","kana":"こにしけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県横手市雄物川町薄井字薄井94","lat":39.32478552,"lng":140.4373462,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積135㎡","structure_material":"土蔵造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"05 － 0159","desc":"主屋の北面東寄りに接続する妻入土蔵。南北棟の切妻造鉄板葺置屋根とする。桁行１４ｍ梁間７．５ｍ規模の２階建で、東面に通り土間を付設する。主屋側の扉は掛子塗で、黒漆喰の磨仕上げとする。地梁に太い垂木を密に架け渡し、力強い内部空間をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007606"},{"id":"00001324","register_sub_id":"101","register_pk":"102314","name":"強首樅峰苑（旧小山田家住宅）","kana":"こわくびしょうほうえん（きゅうおやまだけじゅうたく）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"秋田県","address":"秋田県大仙市強首字強首268","lat":39.55832017,"lng":140.28252596,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積611㎡","structure_material":"木造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"05 － 0055","desc":"強首温泉郷の一画に建つかつての豪農の邸宅。大正３年の秋田県大地震後の再建で，大広間に着脱可能な中央柱を設置するという構法上の工夫が見られる。屋根の千鳥破風，軒唐破風付き入母屋とムクリ破風の玄関が豪壮な正面構えを造る。棟梁は井上喜代松。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001324"},{"id":"00007712","register_sub_id":"101","register_pk":"108694","name":"佐々木家住宅主屋","kana":"ささきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"秋田県","address":"秋田県横手市増田町増田字中町91","lat":39.2045711,"lng":140.5462136,"geo_status":"db","era":"昭和24","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積174㎡","structure_material":"木造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"05 - 0161","desc":"通りから少し入った位置に建つ。建ちの高い木造２階建で、切妻造妻入鉄板葺。正面上部は白漆喰壁に梁と束を組む伝統的な妻面を造る。内部は南側を通り土間とし、前方に座敷など、後方に台所や寝室を配する。通り土間を吹抜けとし、高窓により十分な採光を図る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007712"},{"id":"00002587","register_sub_id":"101","register_pk":"103577","name":"佐々木家住宅主屋","kana":"ささきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県由利本荘市前郷字前郷207","lat":39.31295555,"lng":140.10984159,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積158㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"05 － 0075","desc":"屋敷中央にあり，ほぼ南面して建つ。寄棟造・桟瓦葺，平屋建で，南面と東面に切妻造の玄関を付ける。中央の１５畳和室を取り巻くよう巧みに各室を配し，東南隅には歯科診療室と待合室を設け，電話室もある。地方における数少ない診療所兼用和風住宅の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002587"},{"id":"00002590","register_sub_id":"101","register_pk":"103580","name":"佐々木家住宅小便所","kana":"ささきけじゅうたくしょうべんじょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"秋田県","address":"秋田県由利本荘市前郷字前郷207","lat":39.3129548,"lng":140.11015783,"geo_status":"db","era":"大正3頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"煉瓦造平屋建、鉄板葺、建築面積2.8㎡","structure_material":"煉瓦造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"05 － 0078","desc":"屋敷東側，主屋東面の診療所用玄関の手前に建つ。南北棟の切妻造・鉄板葺で，構造はイギリス積の煉瓦造とし，南面に鉄板張扉の出入口，西面に両開きガラス戸付の欠円アーチ窓を設ける。規模は小さいが，近代の屋敷構成を知る上でも欠かせない存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002590"},{"id":"00002589","register_sub_id":"101","register_pk":"103579","name":"佐々木家住宅文庫蔵","kana":"ささきけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県由利本荘市前郷字前郷207","lat":39.31301352,"lng":140.10963883,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積72㎡","structure_material":"土蔵造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"05 － 0077","desc":"屋敷西側，養老閣後方にある。南北棟で切妻造・桟瓦葺の土蔵で，東面に下屋庇を設け，１階を文書収蔵庫，２階を座敷とする。棟木墨書より年代と棟梁名が判り，外壁煉瓦積は後補であるが，漆喰塗から各部造作まで丁寧なつくりで，この時期の基準となる建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002589"},{"id":"00002588","register_sub_id":"101","register_pk":"103578","name":"佐々木家住宅養老閣","kana":"ささきけじゅうたくようろうかく","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"秋田県","address":"秋田県由利本荘市前郷字前郷207","lat":39.31291431,"lng":140.10968483,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造3階建、鉄板一部瓦葺、建築面積92㎡","structure_material":"木造3階建","registered":"2002.02.14(平成14.02.14)","register_no":"05 － 0076","desc":"主屋西南に廊下で接続する別棟で，養老閣と称されている。木造・３階建で，南北棟・寄棟造の２階に南北棟・寄棟造の望楼風３階を載せ，３階大棟両端に鯱を飾るなど，地域のシンボル的な存在である。内部も透漆を多用し，洋風細部も備え，凝ったつくりである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002588"},{"id":"00011234","register_sub_id":"101","register_pk":"209069","name":"佐々木利三郎家住宅米蔵","kana":"ささきりさぶろうけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県由利本荘市岩城亀田大町字肴町14","lat":39.500878,"lng":140.080497,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積86㎡","structure_material":"土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"05－0210","desc":"敷地北奥に東西棟で建つ二階建土蔵。平入で、南正面には下屋を設けて蔵前とする。小屋は登梁形式である。一階内部は前面の通りと床上部とし、二室に分ける。下屋部分の外壁には商号と家紋、恵比寿と大黒の着彩した鏝絵を左右に描き、高い左官技術を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011234"},{"id":"00011233","register_sub_id":"101","register_pk":"209068","name":"佐々木利三郎家住宅主屋","kana":"ささきりさぶろうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県由利本荘市岩城亀田大町字肴町14","lat":39.500659,"lng":140.080607,"geo_status":"db","era":"明治中期／大正9・昭和13・同34改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、鉄板葺、建築面積235㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"05－0209","desc":"亀田旧城下の町人地に建つ商家。通りに面して玄関を張り出し、大棟の先端を延ばした切妻造妻入の外観を見せる。玄関から続いて土間を通し、左に座敷や居間等を並べる。座敷は、床や棚などの座敷飾を備えた本格的なもの。当地の豪商の暮らしぶりを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011233"},{"id":"00011235","register_sub_id":"101","register_pk":"209070","name":"佐々木利三郎家住宅人形蔵","kana":"ささきりさぶろうけじゅうたくにんぎょうぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県由利本荘市岩城亀田大町字肴町14","lat":39.500766,"lng":140.080479,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積62㎡","structure_material":"土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"05－0211","desc":"敷地西側に南北棟で建つ二階建土蔵。平入で、東正面に下屋を設けて蔵前とする。南・東面では、基礎には切石を貼り、その上部に海鼠壁を貼る。もとは文庫蔵と称しており、家財道具を納めた蔵とみられる。掛子塗の扉や、楣に絵様を入れるなど左官仕事も優秀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011235"},{"id":"00006632","register_sub_id":"101","register_pk":"107615","name":"佐藤養助商店漆蔵資料館土蔵","kana":"さとうようすけしょうてんうるしぐらしりょうかんどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県横手市増田町増田字本町5","lat":39.20538884,"lng":140.54514639,"geo_status":"db","era":"大正10／平成13改修","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"土蔵造2階建、建築面積93㎡","structure_material":"土蔵造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"05 － 0156","desc":"桁行７間梁間４間、土蔵造２階建、切妻造妻入。基礎は切石布積で、側まわりは壁を白と黒の磨漆喰で塗り分け、正面に両開の掛子塗戸をたてる。内部は木太い杉や欅、栗材で組み立て、造作や柱のほか小屋組にまで漆を塗り上げて、華やかに仕上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006632"},{"id":"00003943","register_sub_id":"101","register_pk":"104933","name":"里の家（旧大宮家住宅）主屋","kana":"さとのいえ（きゅうおおみやけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県秋田市雄和妙法字糠塚21","lat":39.594746,"lng":140.18771591,"geo_status":"db","era":"明治17頃／昭和62移築","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造平屋建、茅葺、建築面積270㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"05 － 0095","desc":"もと銅屋地区「肝煎」の居宅。木造平屋建，寄棟造，茅葺の，いわゆる中門造とした大型の農家建築。現在，飲食及び展示施設として利用されている。曲面を上下に重ねた力強い造形を表す中門正面の破風が，繊細な格子窓を備える妻壁に覆い被さるのが特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003943"},{"id":"00007717","register_sub_id":"101","register_pk":"108699","name":"鈴木家住宅旧米蔵","kana":"すずきけじゅうたくきゅうこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市増田町増田字七日町130","lat":39.20284689,"lng":140.54689233,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積75㎡","structure_material":"土蔵造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"05 - 0166","desc":"短冊形の敷地後方に東西棟で建つ。桁行１４ｍ梁間４．８ｍの細長い土蔵で、切妻造鉄板葺の置屋根とする。壁は白漆喰仕上げで、西面に掛子塗の両開戸を構える。内部は西半部が土間で２階床を張り、東半部は板敷で吹抜けとする。簡素ながら良材で造られた土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007717"},{"id":"00000116","register_sub_id":"101","register_pk":"101106","name":"鈴木家住宅主屋","kana":"すずきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"秋田県","address":"秋田県横手市塚堀114","lat":39.33139262,"lng":140.51031331,"geo_status":"db","era":"元治元","year":1864,"year_source":"db","year_min":1864,"year_max":1864,"year_label":null,"structure":"木造平屋建，鉄板葺，建築面積256㎡","structure_material":"木造平屋建","registered":"1997.05.07(平成9.05.07)","register_no":"05 － 0009","desc":"この地方に多い喰違い四間取の平面を保つ切妻造，前後庇付きの比較的規模の大きな住宅で，妻は小屋構造を化粧で表す。座敷廻りの差物の架構は特異で，特に奥座敷に見られる柱を省略するＴ字型の架構の技術は高度で，見るべきものがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000116"},{"id":"00015122","register_sub_id":"101","register_pk":"530546","name":"髙橋家住宅土蔵","kana":"たかはしけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県湯沢市岩崎字岩崎79他","lat":39.20535556,"lng":140.51117222,"geo_status":"db","era":"明治44年","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積131㎡、覆屋付","structure_material":"土蔵造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"05 - 0250","desc":"主屋の南に接続する家財蔵。二階建切妻造妻入で外壁漆喰塗仕上、腰を院内石の切石積とし全体を下部吹放しの鞘で覆う。戸口は楣に精緻な鏝絵を施し、掛子塗扉を吊る。内部は各階一室の板敷で太い二重梁を現す。木部を透漆塗で仕上げ、豪壮かつ華やかな土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015122"},{"id":"00015121","register_sub_id":"101","register_pk":"530545","name":"髙橋家住宅主屋","kana":"たかはししけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県湯沢市岩崎字岩崎79他","lat":39.205475,"lng":140.51098889,"geo_status":"db","era":"明治45年／昭和中期改修","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積332㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"05 - 0249","desc":"旧羽州街道に北面する敷地に建つ旧家の主屋。木造一部二階建で外壁は真壁漆喰塗仕上。北面中央に起屋根の玄関を張出し、背面の庭を取り囲むように座敷を突出させて縁を廻らす。欄間や金具に技巧を凝らし、優美な襖絵で飾った座敷が連なる上質な近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015121"},{"id":"00000619","register_sub_id":"101","register_pk":"101609","name":"田沼家土蔵","kana":"たぬまけどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"秋田県","address":"秋田県男鹿市北浦北浦字池の田12","lat":39.96079993,"lng":139.78193226,"geo_status":"db","era":"江戸期","year":1735,"year_source":"estimated","year_min":1615,"year_max":1867,"year_label":"江戸期","structure":"土蔵造２階建，鋼板葺，建築面積159㎡","structure_material":"土蔵造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"05 － 0025","desc":"田沼家は，明治期に回船業を営み県内一になるほど栄えた家で，土蔵は初代が建てた屋敷に残る唯一の江戸期の建築物と伝える。扉廻り以外を荒壁仕上げとするなど意匠は簡素だが，近辺では数少ない建築年代が古い比較的に規模の大きな土蔵として知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000619"},{"id":"00001028","register_sub_id":"101","register_pk":"102018","name":"戸田家住宅","kana":"とだけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"大正","pref":"秋田県","address":"秋田県横手市黒川字余目196","lat":39.35465366,"lng":140.50002607,"geo_status":"db","era":"大正5頃","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，鉄板葺，建築面積302㎡","structure_material":"木造平屋建","registered":"1999.02.17(平成11.02.17)","register_no":"05 － 0041","desc":"横手市街の北西，大戸川沿いの敷地に建つ。正面西寄りにムクリ破風の玄関を構え，東寄りに切妻破風の土間玄関を設ける。玄関内部を土縁とし，西側座敷回りに縁側をめぐらす。主屋の四周に下屋を回した整った外観を呈する大型農家の好例。棟梁は根田富之助。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001028"},{"id":"00003945","register_sub_id":"101","register_pk":"104935","name":"八森苑","kana":"はちもりえん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県由利本荘市矢島町矢島町55","lat":39.230881,"lng":140.13155559,"geo_status":"db","era":"明治10頃／大正末期増築","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造平屋一部2階建、銅板葺、建築面積345㎡","structure_material":"木造平屋一部2階建","registered":"2004.03.02(平成16.03.02)","register_no":"05 － 0097","desc":"町中心部の旧武家屋敷地に建つ。木造平屋建，寄棟造，平入で，腰を簓子下見板張とし，正面玄関部に起り破風を設け，主屋の背面東北には木造総２階建の離れを矩折れに接続する。離れ内部には随所に銘木を用いる。町の文化施設として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003945"},{"id":"00006330","register_sub_id":"101","register_pk":"107313","name":"山内家住宅裏座敷","kana":"やまうちけじゅうたくうらざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"秋田県","address":"秋田県湯沢市吹張2-1-4","lat":39.15657959,"lng":140.4915248,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋一部2階建、瓦葺、建築面積145㎡","structure_material":"木造平屋一部2階建","registered":"2007.10.02(平成19.10.02)","register_no":"05 － 0150","desc":"敷地の最奥で、主屋側に正面出入口を設け、背面は裏通りに面する。Ｌ字型の平面になり、一部に２階を設ける。主室にはトコと違棚、付書院を設ける。寄棟造桟瓦葺で、外壁を真壁造、一部下見板張とする。軽快な意匠でまとめられた住居である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006330"},{"id":"00006334","register_sub_id":"101","register_pk":"107317","name":"山内家住宅穀蔵","kana":"やまうちけじゅうたくこくぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県湯沢市吹張2-1-4","lat":39.15667791,"lng":140.49166597,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積53㎡","structure_material":"土蔵造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"05 － 0154","desc":"文庫蔵と商品蔵の後方、南北棟で建つ。桁行５間、梁間３間規模の土蔵造２階建である。屋根は切妻造、鉄板葺。外壁はモルタル塗で、平と妻面に両開戸をたてる。規模に対して、たちが比較的低く、安定感のある外観になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006334"},{"id":"00006335","register_sub_id":"101","register_pk":"107318","name":"山内家住宅車庫","kana":"やまうちけじゅうたくしゃこ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"秋田県","address":"秋田県湯沢市吹張2-1-4","lat":39.15681602,"lng":140.49213783,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"コンクリート造平屋建、鉄板葺、建築面積26㎡","structure_material":"コンクリート造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"05 － 0155","desc":"主屋の北側、羽州街道に面して建つ。桁行７．３ｍ、梁間３．６ｍ、切妻造妻入鉄板葺。コンクリート造で、正面に間口一杯の開口、背面に引違の出入口をあける。開口には庇を掛け、庇軒下に渦巻き状の意匠の持送りを設ける。主屋とともに優れた街路景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006335"},{"id":"00006329","register_sub_id":"101","register_pk":"107312","name":"山内家住宅主屋","kana":"やまうちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県湯沢市吹張2-1-4","lat":39.15672142,"lng":140.49211028,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積258㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"05 － 0149","desc":"羽州街道沿いに建つ町家。桁行１２間半、梁間５間半の切妻造妻入２階建で、深緑の釉薬瓦で葺かれる。正面を店舗とし、その奥片側に通り土間、２階に主座敷を設ける。梁を数段重ねた妻面や、正・側面に取り付く多くの庇などが変化に富む外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006329"},{"id":"00006333","register_sub_id":"101","register_pk":"107316","name":"山内家住宅商品蔵","kana":"やまうちけじゅうたくしょうひんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県湯沢市吹張2-1-4","lat":39.15663432,"lng":140.4918094,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"05 － 0153","desc":"文庫蔵の南側に並行して建つ。桁行５間、梁間３間の規模をもつ土蔵造２階建で、切妻造鉄板葺の置屋根とする。外壁はモルタル塗で、窓は両開戸とし、庇を持送りで支持する。敷地内の蔵は同じ意匠で外観が構成され、主屋後方の屋敷構えに統一感を与えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006333"},{"id":"00006331","register_sub_id":"101","register_pk":"107314","name":"山内家住宅道具蔵","kana":"やまうちけじゅうたくどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県湯沢市吹張2-1-4","lat":39.1568026,"lng":140.49183795,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積54㎡","structure_material":"土蔵造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"05 － 0152","desc":"文庫蔵と並行して、その北側やや前方に建つ。桁行６間半、梁間２間半と桁行の長い土蔵である。切妻造鉄板葺の置屋根で、外壁はモルタル塗仕上げである。平と妻側に出入口を設け、窓に庇を付ける。装飾的要素を廃し、落ち着きのある外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006331"},{"id":"00006332","register_sub_id":"101","register_pk":"107315","name":"山内家住宅文庫蔵","kana":"やまうちけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県湯沢市吹張2-1-4","lat":39.15672236,"lng":140.49183247,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積96㎡","structure_material":"土蔵造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"05 － 0151","desc":"桁行７間、梁間４間の規模をもつ切妻造妻入鉄板葺の土蔵造２階建で、主屋背後に東西棟で建つ。外壁はモルタル塗で、開口に両開戸をたてる。１階内部後半の床は一段高く、その境に欄間などを設ける。外観は簡明で、内部は太い材を用い力強い意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006332"},{"id":"00008411","register_sub_id":"101","register_pk":"134807","name":"渡邊家住宅主屋","kana":"わたなべけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県仙北市角館町横町51-1他","lat":39.59561415,"lng":140.56328978,"geo_status":"db","era":"明治後期／平成17年移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、鉄板葺、建築面積59㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"05 － 0183","desc":"東西に走る通りに北面して建つ。木造二階建、南北棟の切妻造妻入鉄板葺、間口五・二メートル奥行一一メートル。妻に小屋組を現し、二階座敷に面して全面を開口とし、一階にはコモセと称する下屋を付ける。角館に残る数少ない町家で、伝統的な表構えを残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008411"},{"id":"00005403","register_sub_id":"101","register_pk":"106391","name":"渡部家住宅主屋","kana":"わたなべけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県鹿角市八幡平字石鳥谷63","lat":40.14978321,"lng":140.77801631,"geo_status":"db","era":"明治24","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積374㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"05 － 0137","desc":"在郷武士の家系をひく地主住宅で，桁行１４間，梁間７間規模，寄棟造，もと茅葺で，正面西南に玄関と小座敷を突き出す。たちが高く，小さな土間と２４畳半敷の大座敷に特色があり，用材や造作も上質である。記録から上棟年と大工棟梁浅利重吉が判明している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005403"},{"id":"00005404","register_sub_id":"101","register_pk":"106392","name":"渡部家住宅土蔵","kana":"わたなべけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県鹿角市八幡平字石鳥谷63","lat":40.15008186,"lng":140.77812935,"geo_status":"db","era":"明治35","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積124㎡","structure_material":"土蔵造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"05 － 0138","desc":"主屋の東北に位置する。桁行８間，梁間４間の比較的規模の大きな土蔵造２階建の米蔵で，南面に庇を付けて戸口を設け，主屋の棟とは４５度振ったもと柾葺の切妻屋根を架ける。記録から，主屋と同じ大工棟梁の建設になることが判明する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005404"},{"id":"00005405","register_sub_id":"101","register_pk":"106393","name":"渡部家住宅門","kana":"わたなべけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"秋田県","address":"秋田県鹿角市八幡平字石鳥谷63","lat":40.14962,"lng":140.778244,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、鉄板葺、間口4.7m、石段付","structure_material":"木造","registered":"2006.03.27(平成18.03.27)","register_no":"05 － 0139","desc":"主屋の南方に建つ。礎石建ちの一間一戸の木造薬医門で，間口規模を４．７ｍとし，鉄板葺（もと柾葺）の切妻屋根を架ける。扉を設けない開放的な門で，主柱手前左右に長２．８ｍの板壁を配する。アプローチの石段とともに屋敷地の表構えをつくる要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005405"},{"id":"00000629","register_sub_id":"101","register_pk":"101619","name":"阿久津家住宅（糸沢本陣）米蔵","kana":"あくつけじゅうたく（いとざわほんじん）こめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県南会津郡南会津町糸沢字居平1949","lat":37.13163127,"lng":139.71557495,"geo_status":"db","era":"安政6","year":1859,"year_source":"db","year_min":1859,"year_max":1859,"year_label":null,"structure":"土蔵造２階建，鉄板葺，建築面積82㎡","structure_material":"土蔵造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"07 － 0022","desc":"屋敷地の東北部に建つ。平入，置屋根形式の土蔵で，かって存在した六つの土蔵のうちのひとつ。太い棟木の下面に残された墨書から２０代当主の時代に建設されたことが判明している。２０年位前に補修されているが，現在も阿久津家の蔵として使用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000629"},{"id":"00000628","register_sub_id":"101","register_pk":"101618","name":"阿久津家住宅（糸沢本陣）主屋","kana":"あくつけじゅうたく（いとざわほんじん）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県南会津郡南会津町糸沢字居平1949","lat":37.13161154,"lng":139.71573979,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建，鉄板葺，建築面積440㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"07 － 0021","desc":"旧日光街道沿いの旧家で，敷地のやや奥まったところに建ち，間口１６間半，奥行９間の規模を有する。かっては茅葺で，以前は６棟の蔵が主屋を取り囲んでいた。この地域の交易の中心的役割を果たしてきた家で，問屋本陣とも呼ばれ親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000628"},{"id":"00006994","register_sub_id":"101","register_pk":"107976","name":"阿部家住宅石蔵","kana":"あべけじゅうたくいしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県福島市笹木野字萱場24-1他","lat":37.78106466,"lng":140.40858096,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"石造2階建、鉄板葺、建築面積46㎡","structure_material":"石造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"07 － 0098","desc":"主屋の東、蚕蔵の西に建つ石造２階建。桁行９．６ｍ梁間４．８ｍの東西棟で、置屋根鉄板葺とし、西面に鉄板葺庇を付けて戸口を開く。外壁は凝灰岩切石積で腰に水切りを付け、鉢巻も石製とする。２階両妻に窓を開く。小屋組はキングポスト・トラス。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006994"},{"id":"00006993","register_sub_id":"101","register_pk":"107975","name":"阿部家住宅蚕蔵","kana":"あべけじゅうたくかいこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県福島市笹木野字萱場24-1他","lat":37.7810828,"lng":140.4087101,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積43㎡","structure_material":"土蔵造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"07 － 0097","desc":"敷地の東辺中央、街路に面して建つ土蔵造２階建。桁行７．９ｍ梁間５．４ｍの切妻造桟瓦葺で、西面に鉄板葺庇を付ける。戸口は西面２ヶ所、南・北面に各１ヶ所を開く。１階を繭置場、２階を使用人室に用いた。白漆喰塗外壁の腰を海鼠壁とする。赤瓦が目をひく。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006993"},{"id":"00006991","register_sub_id":"101","register_pk":"107973","name":"阿部家住宅上座敷","kana":"あべけじゅうたくかみざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県福島市笹木野字萱場24-1他","lat":37.78097342,"lng":140.40816586,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"木造平屋建、銅板葺、建築面積113㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"07 － 0095","desc":"主屋の南西に位置する木造平屋建の東西棟で、主屋の前身建物の背面に接続していた。屋根は西が入母屋造、東が切妻造で銅板葺とし、南、西、北に庇を巡らせ縁とする。内部は田の字型に８畳２室と６畳２室を配する。落ち着いた屋敷構えを創出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006991"},{"id":"00006989","register_sub_id":"101","register_pk":"107971","name":"阿部家住宅主屋","kana":"あべけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"福島県","address":"福島県福島市笹木野字萱場24-1他","lat":37.781048,"lng":140.408356,"geo_status":"db","era":"昭和28","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造2階建、瓦葺、建築面積156㎡","structure_material":"木造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"07 － 0093","desc":"敷地の中央に東西棟で建つ木造２階建。入母屋造瓦葺で、東妻に玄関を設け、南東に応接室、北西に台所等が附属する。１階南面には１間幅の広縁を設ける。上下階とも部屋境が土壁。室の独立性が高く、居住空間を重視した住宅建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006989"},{"id":"00006990","register_sub_id":"101","register_pk":"107972","name":"阿部家住宅離れ座敷","kana":"あべけじゅうたくはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県福島市笹木野字萱場24-1他","lat":37.78085631,"lng":140.40826162,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積93㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"07 － 0094","desc":"主屋の南方に位置する木造平屋建の南北棟で、主屋の前身建物に接続していた。屋根は南が入母屋造、北が切妻造で瓦葺とし、四周に鉄板葺庇を巡らせて縁とする。平面は８畳と６畳の座敷２室からなる。面皮の長押など良材を用い、造作も丁寧である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006990"},{"id":"00006997","register_sub_id":"101","register_pk":"107979","name":"阿部家住宅文庫蔵","kana":"あべけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県福島市笹木野字萱場24-1他","lat":37.78099417,"lng":140.40801214,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"07 － 0101","desc":"上座敷の西、煉瓦蔵の東に建つ土蔵造２階建である。桁行７．９ｍ梁間５．０ｍの南北棟で、切妻造の置屋根を桟瓦葺とする。切石積上に建ち、外壁は白漆喰塗で、置屋根の軒先まで塗り上げる。腰はモルタル塗である。南妻面窓の黒漆喰塗扉が重厚である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006997"},{"id":"00006992","register_sub_id":"101","register_pk":"107974","name":"阿部家住宅前の蔵","kana":"あべけじゅうたくまえのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県福島市笹木野字萱場24-1他","lat":37.7806779,"lng":140.40845414,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、鉄板葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"07 － 0096","desc":"敷地の南東隅に位置する土蔵造２階建である。桁行７．８ｍ梁間５．２ｍの東西棟で、切妻造の置屋根鉄板葺とする。北面と西面に鉄板葺庇を付けて西妻に扉口を設ける。切石基礎上に建ち、外壁は白漆喰塗で、鉢巻を黒漆喰塗として外観のアクセントとしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006992"},{"id":"00006995","register_sub_id":"101","register_pk":"107977","name":"阿部家住宅味噌蔵","kana":"あべけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県福島市笹木野字萱場24-1他","lat":37.78122628,"lng":140.40837814,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、鉄板葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"07 － 0099","desc":"主屋の北に位置する土蔵造２階建である。桁行６．２ｍ梁間４．１ｍの南北棟で、切妻造の置屋根を鉄板葺とする。外壁は土壁で、腰をモルタル塗とする。南妻面に鉄扉付の戸口を設け、１階東面と２階南面に窓を開く。開口部まわりの白漆喰塗がアクセントとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006995"},{"id":"00006996","register_sub_id":"101","register_pk":"107978","name":"阿部家住宅煉瓦蔵","kana":"あべけじゅうたくれんがぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県福島市笹木野字萱場24-1他","lat":37.78112493,"lng":140.40811979,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"土蔵造2階建、瓦葺、建築面積109㎡","structure_material":"土蔵造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"07 － 0100","desc":"主屋の西、上座敷の北西角に接続して建つ土蔵造２階建。桁行１６ｍ梁間６．７ｍの南北棟で、切妻造桟瓦葺とし、東面の蔵前は鉄板葺とする。外壁は漆喰塗で腰を煉瓦張、蔵前はモルタル仕上げ。１階南半に１５畳蔵座敷を設け、北半は什器蔵、２階は衣装蔵とした。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006996"},{"id":"00012488","register_sub_id":"101","register_pk":"367783","name":"天野家住宅米蔵","kana":"あまのけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県南相馬市小高区耳谷字桃内28","lat":37.530407,"lng":140.982529,"geo_status":"geocoded","era":"大正15年","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積57㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"07 － 0203","desc":"敷地東南隅に建つ。土蔵造二階建、置屋根式の切妻造妻入で、北面中央に扉口を開き、下屋を設ける。外壁は一階を海鼠壁とする。柱を半間毎に立て、小屋に曲り梁とトラスを併用するなど堅牢につくる。敷地正面の石垣上にあって格式ある表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012488"},{"id":"00012487","register_sub_id":"101","register_pk":"367782","name":"天野家住宅主屋","kana":"あまのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県南相馬市小高区耳谷字桃内28","lat":37.530407,"lng":140.982529,"geo_status":"geocoded","era":"明治44年／昭和2年改修","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積234㎡","structure_material":"木造2階一部平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"07 － 0202","desc":"旧小高町郊外にある肝煎を務めた旧家。主屋は敷地中央に南面して建つ。居室部は入母屋造の二階建で正面に起りのある切妻造の玄関を出し、東側面に平屋建の台所部が接続する。居室部は2列2室で一階前面と二階に座敷を配する。地域を代表する上質な和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012487"},{"id":"00012491","register_sub_id":"101","register_pk":"367786","name":"天野家住宅正門","kana":"あまのけじゅうたくせいもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県南相馬市小高区耳谷字桃内28","lat":37.530407,"lng":140.982529,"geo_status":"geocoded","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"石造、間口3.2m、左右脇門付","structure_material":"石造","registered":"2018.11.02(平成30.11.02)","register_no":"07 － 0206","desc":"敷地南面中央部に引き込んだ斜路の突当りに南面して建つ。花崗岩製で、高さ3メートル、間口3・2メートルの門柱の両脇に鳥居形の脇門を付す。柱頭を四角錐の銅板巻で飾り、内外の地面を石敷で仕上げる。均整のとれた形態で格式ある表構えの核をなしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012491"},{"id":"00012490","register_sub_id":"101","register_pk":"367785","name":"天野家住宅外便所","kana":"あまのけじゅうたくそとべんじょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県南相馬市小高区耳谷字桃内28","lat":37.530407,"lng":140.982529,"geo_status":"geocoded","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積5.6㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"07 － 0205","desc":"敷地東北部に西面して建つ。南北棟の切妻造、平屋建で、南端に開放の小便所、中央と北端に大便所を設ける。梁を延ばして軒桁を持ち出し、吹寄せ小舞野地の軒天井をつくるなど要所を数寄屋風に仕上げる。小ぶりな附属建物ながら、繊細な意匠をもつ佳品である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012490"},{"id":"00012492","register_sub_id":"101","register_pk":"367787","name":"天野家住宅通用門・裏門及び塀","kana":"あまのけじゅうたくつうようもん・うらもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県南相馬市小高区耳谷字桃内28","lat":37.530407,"lng":140.982529,"geo_status":"geocoded","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"通用門 鉄筋コンクリート造、間口2.8m 裏門 鉄筋コンクリート造、間口2.1m 塀 鉄筋コンクリート造、総延長100m","structure_material":"通用門 鉄筋コンクリート造","registered":"2018.11.02(平成30.11.02)","register_no":"07 － 0207","desc":"敷地の南面と東面の境を区切る塀で、南面中央は正門に接続し南面西端に通用門、東面北端に裏門を開く。鉄筋コンクリート造で、基底部と笠石に花崗岩を用い、壁面をモルタル仕上、各門柱をコンクリート洗出し仕上とする。格式ある屋敷構えを重厚にまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012492"},{"id":"00012489","register_sub_id":"101","register_pk":"367784","name":"天野家住宅西蔵","kana":"あまのけじゅうたくにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県南相馬市小高区耳谷字桃内28","lat":37.530407,"lng":140.982529,"geo_status":"geocoded","era":"明治前期／昭和前期改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"07 － 0204","desc":"敷地南面の西寄りに建つ家財蔵。土蔵造二階建、置屋根式の切妻造妻入で、北面中央に扉口を開き、下屋を設ける。外壁は腰壁を海鼠壁とする。通し柱を1尺間隔に立てる頑丈なつくりで、小屋は登梁とする。米蔵と同じく格式ある表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012489"},{"id":"00011859","register_sub_id":"101","register_pk":"211047","name":"有賀家住宅蔵座敷及び控えの間","kana":"ありがけじゅうたくくらざしきおよびひかえのま","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県石川郡石川町大字形見字尾巻124","lat":37.146217,"lng":140.481923,"geo_status":"db","era":"大正前期／昭和23年頃改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"土蔵造二階建及び木造平屋建、瓦葺、建築面積88㎡","structure_material":"土蔵造二階建及び木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"07-183","desc":"御斎所街道沿いの敷地奥に南面する。蔵座敷は土蔵造、切妻造妻入で、西に木造平屋建の控えの間を付す。蔵座敷は一階を座敷二室、二階を物置とし、座敷は床・床脇・付書院を設け、銘木を用い欄間等建具に意匠を凝らす。養蚕農家の生活を支える蔵座敷の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011859"},{"id":"00013034","register_sub_id":"101","register_pk":"368342","name":"石田家住宅主屋","kana":"いしだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県双葉郡大熊町大字大川原字西平160","lat":37.38722222,"lng":140.95174167,"geo_status":"db","era":"江戸末期／昭和33年頃改修、同45年頃増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積230㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"07 － 0227","desc":"大熊町中央の山裾に位置し、主屋は敷地奥中央に南面して建つ。入母屋造桟瓦葺の屋根は当初茅葺であったが、改修時に小屋組を刷新した。内部は南北二列に三室ずつ並び、西端奥の座敷には床、棚、付書院を備える。浜通りの上層農家の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013034"},{"id":"00013035","register_sub_id":"101","register_pk":"368343","name":"石田家住宅土蔵","kana":"いしだけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県双葉郡大熊町大字大川原字西平160","lat":37.38703333,"lng":140.95178333,"geo_status":"db","era":"明治前期／平成元年頃改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積45㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"07 － 0228","desc":"主屋の西寄り前方に東西棟で建つ。土蔵造二階建、置屋根形式の切妻造桟瓦葺で、北、東面に下屋を付し、東妻の下屋を蔵前とし、扉口を設ける。内部は一階が土間、二階が板敷で、小屋組は桁行中央の梁に束を立て棟木を支える。農家の屋敷構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013035"},{"id":"00013036","register_sub_id":"101","register_pk":"368344","name":"石田家住宅籾蔵","kana":"いしだけじゅうたくもみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県双葉郡大熊町大字大川原字西平160","lat":37.38705,"lng":140.95160833,"geo_status":"db","era":"昭和前期／平成18年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、金属板葺、建築面積11㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"07 － 0229","desc":"主屋の西側に南北棟で建つ。木造平屋建、切妻造金属板葺の板倉で、籾米を貯蔵していた。土台より一段上げて床を張り、東西両面に入口を設ける。桁行柱間四間で柱位置に梁を架け、中央のみ梁に束を立て棟木を支持する。伝統的な屋敷構えを構成する要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013036"},{"id":"00013037","register_sub_id":"101","register_pk":"368345","name":"石田家住宅門","kana":"いしだけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県双葉郡大熊町大字大川原字西平160","lat":37.38706667,"lng":140.95191944,"geo_status":"db","era":"明治中期／平成18年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、間口2.7m","structure_material":"木造","registered":"2019.12.05(令和1.12.05)","register_no":"07 － 0230","desc":"敷地南面中央にあり、敷地南側を流れる水路に架かる石橋を覆うように建つ。桁行、梁間とも一間、切妻造桟瓦葺。正背面の柱間に架ける桁上に梁を渡し、その鼻先で軒桁を、梁中央に立つ束で棟木を受ける。伝統的な農家の表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013037"},{"id":"00008250","register_sub_id":"101","register_pk":"133892","name":"上野家住宅旧穀蔵","kana":"うえのけじゅうたくきゅうこくぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県喜多方市松山町村松字常盤町2740-1","lat":37.67184572,"lng":139.8709941,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積87㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"07 － 0112","desc":"味噌蔵の西に東西棟で接続する。桁行１４ｍ梁間５．７ｍと規模の大きい土蔵造２階建で、切妻造桟瓦葺とする。自然石上に切石布基礎をまわし、腰板張の漆喰仕上げとする。南面には東寄りに庇付の出入口を設け、１、２階に窓を穿ち、リズム感のある正面をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008250"},{"id":"00008248","register_sub_id":"101","register_pk":"133890","name":"上野家住宅主屋","kana":"うえのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県喜多方市松山町村松字常盤町2740-1","lat":37.67177893,"lng":139.87123474,"geo_status":"db","era":"明治9年","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積313㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"07 － 0110","desc":"通りに東面してたち、東西棟の蔵座敷に南北棟の旧店舗蔵がＬ字型に接続し、背後に勝手や旧作業蔵を付設する。土蔵造２階建で、漆喰仕上げとし、桟瓦を葺く。蔵座敷１階に十八畳の座敷を設け、トコや棚、付書院を構え、漆塗を施す。大規模な蔵造町家の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008248"},{"id":"00008252","register_sub_id":"101","register_pk":"133894","name":"上野家住宅調度蔵","kana":"うえのけじゅうたくちょうどぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県喜多方市松山町村松字常盤町2740-1","lat":37.67175349,"lng":139.87096018,"geo_status":"db","era":"明治9年","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"07 － 0114","desc":"主屋の西、旧穀蔵の南に東西棟で建つ。桁行８．６ｍ梁間４．８ｍの２階建土蔵。切妻造妻入桟瓦葺とし、東面に下屋を付け、出入口とする。切石基礎をまわし、漆喰仕上げで腰板張とする。１階は前後二室に分け、１、２階とも壁板張と丁寧に仕上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008252"},{"id":"00008253","register_sub_id":"101","register_pk":"133895","name":"上野家住宅離屋","kana":"うえのけじゅうたくはなれや","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県喜多方市松山町村松字常盤町2740-1","lat":37.67166444,"lng":139.87109163,"geo_status":"db","era":"大正6年","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積46㎡","structure_material":"土蔵造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"07 － 0115","desc":"主屋の西南に位置し、東面に庭を設ける。南北棟の入母屋造桟瓦葺で、西面に角屋を設けて浴室や便所とする。十畳の一室で、縁を付設し、西面にトコや棚を構える。紫檀や欅、縞柿などの銘木を用い、山水や鶴などの襖絵を飾る。近代における良質な接客空間の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008253"},{"id":"00008249","register_sub_id":"101","register_pk":"133891","name":"上野家住宅味噌蔵","kana":"うえのけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県喜多方市松山町村松字常盤町2740-1","lat":37.67185102,"lng":139.87113509,"geo_status":"db","era":"明治12年","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積29㎡","structure_material":"土蔵造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"07 － 0111","desc":"主屋の旧作業蔵背後に接続する。東西棟の両下造桟瓦葺、桁行７．６ｍ梁間３．８ｍの土蔵造平屋建。外壁は漆喰仕上げで、腰板張とし、南面に出入口と格子窓を穿つ。内部は土間床で、和小屋をあらわす。主屋勝手口に近く、近代における住生活の一端を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008249"},{"id":"00008251","register_sub_id":"101","register_pk":"133893","name":"上野家住宅煉瓦蔵","kana":"うえのけじゅうたくれんがぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県喜多方市松山町村松字常盤町2740-1","lat":37.67182027,"lng":139.87080328,"geo_status":"db","era":"明治後期／平成13年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造2階建、瓦葺、建築面積77㎡","structure_material":"煉瓦造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"07 － 0113","desc":"旧穀蔵の西に南北棟で建つ。桁行１３ｍ梁間５．７ｍの煉瓦造２階建。切妻造桟瓦葺で、軒まわりを白漆喰塗とする。イギリス積で、腰や開口には施釉煉瓦を用い、欠円アーチ形に窓や出入口を開ける。小屋はトラス。漆喰塗土蔵群からなる屋敷景観に変化を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008251"},{"id":"00008254","register_sub_id":"101","register_pk":"133896","name":"上野家住宅煉瓦塀","kana":"うえのけじゅうたくれんがべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県喜多方市松山町村松字常盤町2740-1","lat":37.67187858,"lng":139.87130895,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造、延長24m","structure_material":"煉瓦造","registered":"2010.09.10(平成22.09.10)","register_no":"07 － 0116","desc":"通りから北側隣地境にかけて、矩折にめぐる煉瓦塀で、延長２４ｍを測る。施釉煉瓦のイギリス積で、桟瓦を葺く。通り側は高さ２．６ｍ厚さ３６㎝で、隣地境は３５㎝低くする。通り側の南寄りに開口を設け、鉄扉を吊る。漆喰仕上げの主屋と対照的な意匠で印象的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008254"},{"id":"00011047","register_sub_id":"101","register_pk":"205154","name":"大谷家住宅中蔵","kana":"おおがいけじゅうたくなかぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県南相馬市鹿島区栃窪字小塚64","lat":37.728778,"lng":140.8984,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、鉄板葺、建築面積54㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"07 - 0166","desc":"東蔵の西に並び建つ酒や醤油を納める蔵。土蔵造二階建切妻造妻入、置屋根波形鉄板葺で北に桟瓦葺の庇を付す。東蔵より桁行が半間長いが、壁頂部の渦紋入り鉢巻、腰廻りの海鼠壁などは類似の意匠である。街路に面する配置は、物流拠点であったことを示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011047"},{"id":"00011046","register_sub_id":"101","register_pk":"205153","name":"大谷家住宅東蔵","kana":"おおがいけじゅうたくひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県南相馬市鹿島区栃窪字小塚64","lat":37.728799,"lng":140.898529,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、鉄板葺、建築面積45㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"07 - 0165","desc":"陸前浜街道と奥州街道を結ぶ塩の道沿いに南面して建つ米蔵。土蔵造二階建、切妻造妻入、置屋根波形鉄板葺で、壁頂部に渦紋入り鉢巻、腰廻りに海鼠壁を廻らす。通り側の妻面には窓を一箇所開き、まぐさに植物紋、窓上に水車の家紋の鏝絵を施すなど華やかに飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011046"},{"id":"00011048","register_sub_id":"101","register_pk":"205155","name":"大谷家住宅門","kana":"おおがいけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県南相馬市鹿島区栃窪字小塚64","lat":37.728726,"lng":140.898493,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、間口2.6m、左右袖塀及び潜戸付","structure_material":"木造","registered":"2016.08.01(平成28.08.01)","register_no":"07 - 0167","desc":"東蔵と中蔵の間に建つ。間口二・六メートルの高麗門で、両脇に長さ各一・二メートルの板塀を附属する。門口上部には吹寄襷桟の欄間を嵌める。屋根は釉薬瓦の桟瓦葺で、大棟端部には「大」の字入りの鬼瓦と鯱を据えるなど、小規模ながら重厚な構えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011048"},{"id":"00012484","register_sub_id":"101","register_pk":"367779","name":"太田家住宅米蔵","kana":"おおたけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県南相馬市原町区信田沢北関ノ内12","lat":37.66156,"lng":140.919373,"geo_status":"geocoded","era":"明治32年／平成17年改修","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"土蔵造2階一部地下1階建、瓦葺、建築面積127㎡","structure_material":"土蔵造2階一部地下1階建","registered":"2018.11.02(平成30.11.02)","register_no":"07 － 0199","desc":"主屋背面東方に南面して建つ。土蔵造二階建、東西棟の切妻造で、正面に吹放し下屋を付す。桁行八間梁間四間で、内部は上下階とも3室に分ける。外観は海鼠壁、鉢巻や開口部の黒漆喰塗、朱塗の鉄扉など重厚かつ華やかな仕上で、屋敷構えに彩りを添えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012484"},{"id":"00012483","register_sub_id":"101","register_pk":"367778","name":"太田家住宅主屋","kana":"おおたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県南相馬市原町区信田沢北関ノ内12","lat":37.66156,"lng":140.919373,"geo_status":"geocoded","era":"大正6年／昭和23年頃・同45年頃・平成19年改修","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積259㎡","structure_material":"木造2階一部平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"07 － 0198","desc":"旧原町郊外の地主宅。敷地中央に南面して建つ主屋は、東面半切妻造、西面入母屋造の二階建で、東側面に切妻造平屋建、玄関付の台所部が接続する。軒は出桁造とし、隅部の垂木を扇状に配るなど丁寧につくる。伝統形式に近代的な要素を加味した豪壮な住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012483"},{"id":"00012486","register_sub_id":"101","register_pk":"367781","name":"太田家住宅道具蔵","kana":"おおたけじゅうたくどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県南相馬市原町区信田沢北関ノ内12","lat":37.66156,"lng":140.919373,"geo_status":"geocoded","era":"明治28年／平成23年改修","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"土蔵造2階建、金属板葺、建築面積22㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"07 － 0201","desc":"主屋背面に味噌蔵と並んで南面して建つ。土蔵造二階建、置屋根式の切妻造妻入で、南面に吹放し下屋を付す。桁行三間梁間二間、外壁漆喰壁の腰セメント塗で、正面は戸口を重厚な枠で飾り、妻面の中央に屋号を浮彫する。上層農家の伝統的な構成を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012486"},{"id":"00012485","register_sub_id":"101","register_pk":"367780","name":"太田家住宅味噌蔵","kana":"おおたけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県南相馬市原町区信田沢北関ノ内12","lat":37.66156,"lng":140.919373,"geo_status":"geocoded","era":"明治28年","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造2階建、金属板葺、建築面積16㎡","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"07 － 0200","desc":"主屋背面に道具蔵と並んで南面して建つ。桁行三間梁間二間の二階建、切妻造妻入で、外壁は腰を下見板張とし、南妻窓の上下額縁を繰形で飾る。一階土間、二階板敷、小屋組登梁で、階段はなく床中央部に荷揚げ口を設ける。上層農家の暮らしの一端を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012485"},{"id":"00000513","register_sub_id":"101","register_pk":"101503","name":"奥山家住宅主屋","kana":"おくやまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県伊達郡国見町大字藤田字北11-2","lat":37.87606481,"lng":140.54449177,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積228㎡","structure_material":"木造平屋建","registered":"1998.04.21(平成10.04.21)","register_no":"07 － 0011","desc":"東西棟の座敷部と南側にある洋館との間をつなぐ南北棟の玄関部からなり，Ｌ字形の平面を持つ。木造平屋建，瓦葺の和風の意匠になり，洋館と好対照をなす。欄間彫刻や床の間建具の意匠等には優れた技能が発揮されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000513"},{"id":"00000514","register_sub_id":"101","register_pk":"101504","name":"奥山家住宅洋館","kana":"おくやまけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県伊達郡国見町大字藤田字北7-1","lat":37.8759008,"lng":140.54444398,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建，スレート葺，建築面積106㎡","structure_material":"木造平屋建","registered":"1998.04.21(平成10.04.21)","register_no":"07 － 0012","desc":"主屋の南に建つ，南東隅に八角の塔屋を持つ木造平屋建の建物。外壁はタイル貼りで，窓廻りや腰下等の要所を石貼りとする。この地方では数少ない和洋両方の接客空間を備えた住宅建築で，主要な窓上部石材の幾何学的な形態等に時代の特徴がよくあらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000514"},{"id":"00001547","register_sub_id":"101","register_pk":"102537","name":"小椋家住宅主屋","kana":"おぐらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県南会津郡下郷町大字戸赤字竹ノ子下852","lat":37.25823778,"lng":139.75962972,"geo_status":"db","era":"明治32頃","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積212㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"07 － 0037","desc":"小椋家は江戸中期から昭和初期まで木地職を営んでいた。主屋は正面隅に馬屋を突出させたＬ字型平面の曲り屋で，大工は地元の渡部宇吉と伝える。太い欅柱など良質の材料を用い，建物全体の立ちが高く，内部も天井を高くするなど，近代の民家の特性をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001547"},{"id":"00001548","register_sub_id":"101","register_pk":"102538","name":"小椋家住宅土蔵","kana":"おぐらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県南会津郡下郷町大字戸赤字竹ノ子下852","lat":37.25842903,"lng":139.75971042,"geo_status":"db","era":"明治29","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積42㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"07 － 0038","desc":"ほぼ南面して建つ主屋北東に建ち，切妻造で内部二階とした小規模な標準形式の土蔵。棟木下端の墨書より，明治２９年の建立，大工は渡部平吉と判明する。小椋家が木地職で最も栄えたのは明治中期頃で，主屋とともに，当時の屋敷構えのあり方を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001548"},{"id":"00001857","register_sub_id":"101","register_pk":"102847","name":"御菓子師玉嶋屋内蔵","kana":"おんかししたましまやうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県二本松市本町一丁目86","lat":37.591549,"lng":140.436005,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"07 － 0043","desc":"大火前の主屋に接して建っていた蔵座敷で，昭和初期に現在地に曳家される。桁行５間，梁行２間半規模の，南北棟，切妻造，瓦葺の２階建土蔵で，比較的たちが低く，平入の入口正面に階段を配置する。土台を石，腰を海鼠壁とした丁寧な造りになる蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001857"},{"id":"00007177","register_sub_id":"101","register_pk":"108159","name":"柏原家住宅土蔵","kana":"かしわばらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県いわき市平字新川町54-1","lat":37.05328476,"lng":140.8971741,"geo_status":"db","era":"明治中期／明治後期改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積55㎡","structure_material":"土蔵造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"07 － 0108","desc":"東西に細長い敷地のほぼ中央に建つ。桁行８．２ｍ梁間５．５ｍ規模の切妻造桟瓦葺２階建。西妻面に庇を付け、掛子塗の両開戸を吊り出入口とする。明治３９年大火に北・東面が被災し、フランス積煉瓦壁に改修されており、地域の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007177"},{"id":"00000943","register_sub_id":"101","register_pk":"101933","name":"川島家住宅主屋","kana":"かわしまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県南会津郡南会津町川島字川島平1918","lat":37.16053186,"lng":139.73910363,"geo_status":"db","era":"寛政9","year":1797,"year_source":"db","year_min":1797,"year_max":1797,"year_label":null,"structure":"木造平屋建，鉄板葺，建築面積172㎡","structure_material":"木造平屋建","registered":"1998.12.11(平成10.12.11)","register_no":"07 － 0028","desc":"寛政５年の火災後の再建で，旧日光街道に面する屋敷地の奥に建つ伝統的な寄棟造，もと茅葺の大規模な農家建築。柱梁等は，木柄の太い地元産の赤松の良材を用い，全体に力強い構成になる。水回り等に改造はあるが，全体に保存は良い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000943"},{"id":"00002743","register_sub_id":"101","register_pk":"103733","name":"木田家住宅主屋","kana":"きだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県いわき市平下平窪字鍛冶内41","lat":37.078861,"lng":140.881958,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積195㎡","structure_material":"木造平屋一部2階建","registered":"2002.06.25(平成14.06.25)","register_no":"07 － 0066","desc":"市街地北部，国道３３９号の近くに位置する。寄棟造・平入で，腰と玄関及び縁側戸袋を簓子下見板張とする。全面に２間半づつの指し鴨居を用いた豪壮な造りと，その上部に嵌め込んだ繊細な格子戸が特徴的な正面立面と，正面全面の化粧軒裏を主な見所とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002743"},{"id":"00002745","register_sub_id":"101","register_pk":"103735","name":"木田家住宅土蔵","kana":"きだけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県いわき市平下平窪字鍛冶内41","lat":37.078957,"lng":140.881836,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積43㎡","structure_material":"土蔵造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"07 － 0068","desc":"主屋の北側，敷地の奥に構える。切妻造，桟瓦葺，２階建，妻入，外装漆喰塗りの土蔵で，大振りな軒蛇腹が，外観にうまく変化を与えている。全体的に簡素な外観ながらも，屋敷構えに欠くことのできない構成要素となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002745"},{"id":"00002744","register_sub_id":"101","register_pk":"103734","name":"木田家住宅煉瓦蔵","kana":"きだけじゅうたくれんがぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県いわき市平下平窪字鍛冶内41","lat":37.078686,"lng":140.881927,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積21㎡","structure_material":"煉瓦造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"07 － 0067","desc":"主屋の南側，敷地の手前にある２階建，桟瓦葺の煉瓦蔵。上下二段の矩形窓を妻側に，二枚厚の楕円形アーチの入口を平側に設け，３段に迫り出した軒蛇腹で外観を引き締める。小口２列と長手１列が交互にあらわれる変則的な煉瓦積を特徴とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002744"},{"id":"00012874","register_sub_id":"101","register_pk":"367982","name":"旧天田愚庵邸","kana":"きゅうあまだぐあんてい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県いわき市平字古鍛冶町47-1","lat":37.05600278,"lng":140.88204444,"geo_status":"db","era":"明治33年／昭和41年移築","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造平屋建、茅葺、建築面積56㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"07 － 212","desc":"松ヶ岡公園に移築保存した歌人・天田愚庵旧居。東面入母屋造、西面切妻造茅葺、東西に座敷と茶室を並べ、東南隅に仏間を設ける。細身の皮付柱を基調に端正にまとめつつ、座敷飾は松と竹の丸太を用いて大仰につくるなど、近代の文人趣味を伝える数寄屋建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012874"},{"id":"00002110","register_sub_id":"101","register_pk":"103100","name":"旧甲斐家住宅蔵座敷","kana":"きゅうかいけじゅうたくくらざしき","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県喜多方市字一丁目4611-1他","lat":37.656528,"lng":139.87178,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積169㎡","structure_material":"土蔵造2階建","registered":"2001.04.24(平成13.04.24)","register_no":"07 － 0048","desc":"甲斐家は江戸期には酒造業，明治以降は味噌・醤油等の醸造業を営んだ。敷地奥に建つ蔵座敷は２階建の土蔵造で，良質の材料を用いる。１階はともに床・床脇付の２１畳の上段ノ間と１８畳の次ノ間とし，２階を物置とする。この地域でも大規模かつ重厚な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002110"},{"id":"00013032","register_sub_id":"101","register_pk":"368227","name":"旧熊倉家住宅主屋","kana":"きゅうくまくらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県伊達市梁川町字右城町48","lat":37.85705,"lng":140.60788889,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"鉄筋コンクリート造2階一部3階建、建築面積120㎡","structure_material":"鉄筋コンクリート造2階一部3階建","registered":"2019.12.05(令和1.12.05)","register_no":"07 － 0225","desc":"町の中心部に建つ個人住宅。鉄筋コンクリート造二階建、三階に展望室を備える。ドイツ壁仕上の簡素な外観で、玄関とベランダを洋風意匠で装飾する。内部は和室を基本としつつ、玄関回りに洋室を配す。地方における洋風意匠の展開の一端を示す住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013032"},{"id":"00013033","register_sub_id":"101","register_pk":"368228","name":"旧熊倉家住宅土蔵","kana":"きゅうくまくらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県伊達市梁川町字右城町48","lat":37.85696389,"lng":140.608175,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積45㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"07 － 0226","desc":"主屋の東背面に建つ土蔵造二階建の蔵。東西棟の切妻造、桟瓦葺とし、西正面に下屋を付す。外壁は漆喰塗で鉢巻を二段に廻らし、垂木まで塗込めた丁寧なつくり。２階西面開口部廻りを黒漆喰塗として全体を引締める。地方有力者の屋敷地の構えを引き立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013033"},{"id":"00011855","register_sub_id":"101","register_pk":"211043","name":"旧鍋三本店（星野家住宅）客座敷","kana":"きゅうなべさんほんてん（ほしのけじゅうたく）きゃくざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福島県","address":"福島県会津若松市材木町二丁目12-2","lat":37.484821,"lng":139.911152,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積66㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"07-179","desc":"若松城西方の材木町に位置する敷地の西寄りに建つ。南北棟の入母屋造、桟瓦葺で、小屋組はキングポストトラス。一〇畳と八畳の座敷を並べ、正側面に廊下を廻し庭園を望む。内法が高く、吟味された材を用い、床脇の天袋を襖絵で飾る良質な近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011855"},{"id":"00011856","register_sub_id":"101","register_pk":"211044","name":"旧鍋三本店（星野家住宅）土蔵","kana":"きゅうなべさんほんてん（ほしのけじゅうたく）どぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県会津若松市材木町二丁目12-2","lat":37.484724,"lng":139.911057,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積38㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"07-180","desc":"客座敷の南西に廊下で繋ぐ。東西棟の切妻造、桟瓦葺で、小屋組をキングポストトラスとする。扉口は幅一間で、土戸、内格子戸片引きを建て込み、土戸には木瓜枠を黒漆喰塗で仕上げる。側背面の窓も鳥居枠で飾り、鉄格子を入れる重厚な構えの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011856"},{"id":"00014728","register_sub_id":"101","register_pk":"518986","name":"旧二階堂家住宅主屋","kana":"きゅうにかいどうけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県福島市上鳥渡字大畑1-1","lat":37.72866944,"lng":140.40825833,"geo_status":"db","era":"江戸後期／明治20年頃増築、昭和55年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、鉄板葺、建築面積321㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"07 - 0279","desc":"福島市南西の農村集落に位置する名主の屋敷。主屋は敷地中央に東面する桁行15間梁間6間半、入母屋造鉄板葺で、南半は広い土間で梁組を現し、北半に四列に部屋を配し、北列を続き間座敷とする。柱の面取大きく古式で、式台玄関など格式を備えた大規模民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014728"},{"id":"00014729","register_sub_id":"101","register_pk":"518987","name":"旧二階堂家住宅長屋門","kana":"きゅうにかいどうけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県福島市上鳥渡字大畑1-1","lat":37.72868333,"lng":140.40860833,"geo_status":"db","era":"江戸末期／明治28年増築、昭和55年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、鉄板葺、建築面積98㎡","structure_material":"土蔵造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"07 - 0280","desc":"敷地東面に建つ平屋建入母屋造鉄板葺の長屋門。南北棟で中央北寄りを門口とし、北と南に下屋を付す。外壁は柱を塗込めた大壁で、東面三箇所に無双窓を開ける。内部は門口の北に厩、南に使用人部屋を配す。江戸末期に遡る大規模な長屋門で、旧家の風格を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014729"},{"id":"00013223","register_sub_id":"101","register_pk":"366212","name":"旧堀切家住宅表門","kana":"きゅうほりきりけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県福島市飯坂町字東滝ノ町16","lat":37.83333611,"lng":140.45206667,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、間口2.6m、袖壁付","structure_material":"木造","registered":"2020.04.03(令和2.04.03)","register_no":"07 － 0236","desc":"敷地西辺に開く表門。間口2・6メートルの棟門形式で、屋根は切妻造銅板葺、一軒繁垂木である。本柱の背面に控柱を立て二段に貫をつないで支え、両妻面の破風板拝みに懸魚を飾り、南脇に袖塀が取り付く。旧家の風格ある表構えを構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013223"},{"id":"00013218","register_sub_id":"101","register_pk":"366207","name":"旧堀切家住宅主屋","kana":"きゅうほりきりけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県福島市飯坂町字東滝ノ町16","lat":37.83339167,"lng":140.45229722,"geo_status":"db","era":"明治14年","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積281㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"07 － 0231","desc":"市中東部の摺上川右岸に位置し、敷地西側に南面して建つ。屋根は寄棟造スレート葺で、南正面に入母屋造の玄関と大振りの千鳥破風を重ねる。次の間は竿縁天井を円弧状に折上げ天井を高めるなど意匠を凝らす。希少な天然スレート葺の近代和風建築の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013218"},{"id":"00013222","register_sub_id":"101","register_pk":"366211","name":"旧堀切家住宅書庫","kana":"きゅうほりきりけじゅうたくしょこ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"福島県","address":"福島県福島市飯坂町字東滝ノ町16","lat":37.83336667,"lng":140.45209167,"geo_status":"db","era":"昭和40年頃","year":1965,"year_source":"db","year_min":1965,"year_max":1965,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積11㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"07 － 0235","desc":"主屋の南西隅に建ち、廊下で接続する。木造平屋建、入母屋造桟瓦葺、外壁は腰壁を下見板張、腰上を漆喰塗とする。十七代当主が弁護士業務の書庫兼書斎として建てた。表門とともに街路沿いの景観を整える主要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013222"},{"id":"00013219","register_sub_id":"101","register_pk":"366208","name":"旧堀切家住宅新蔵","kana":"きゅうほりきりけじゅうたくしんくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県福島市飯坂町字東滝ノ町16","lat":37.83350278,"lng":140.45222222,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積28㎡","structure_material":"土蔵造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"07 － 0232","desc":"敷地西辺で主屋の北側に建ち、廊下で接続する。土蔵造二階建、桁行2間半、梁間2間、南北棟の切妻造で赤瓦の桟瓦葺とする。外壁は漆喰塗で、2階南面に窓を開き、庇を雲形の持送で支える。軒周りに鉢巻を、腰に水切を廻す等丁寧な造りの土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013219"},{"id":"00013221","register_sub_id":"101","register_pk":"366210","name":"旧堀切家住宅道具蔵","kana":"きゅうほりきりけじゅうたくどうぐくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県福島市飯坂町字東滝ノ町16","lat":37.83344722,"lng":140.45241944,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積37㎡","structure_material":"土蔵造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"07 － 0234","desc":"主屋北東に廊下で接続する道具蔵。土蔵造二階建、桁行4間、梁間2間半、南北棟の切妻造で、赤色の桟瓦葺とする。戸口や窓には漆喰塗の両開土戸を建てる。敷地内の蔵は同じ意匠で外観が構成され、主屋後方の屋敷構えに統一感を与えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013221"},{"id":"00013220","register_sub_id":"101","register_pk":"366209","name":"旧堀切家住宅中蔵","kana":"きゅうほりきりけじゅうたくなかのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県福島市飯坂町字東滝ノ町16","lat":37.83347778,"lng":140.452325,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"07 － 0233","desc":"主屋の北側に建つ。土蔵造二階建、桁行3間、梁間2間、東西棟の切妻造で赤色の桟瓦葺とする。一階は床の間を設えた座敷とし、中央に耐火金庫を置く。南面に両開土戸を設け、窓に庇を付ける。装飾的要素を抑え、落ち着きのある外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013220"},{"id":"00013345","register_sub_id":"101","register_pk":"368433","name":"旧吉田家住宅主屋","kana":"きゅうよしだけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県田村郡三春町字大町82","lat":37.4431,"lng":140.48929444,"geo_status":"db","era":"明治28年頃","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積156㎡","structure_material":"木造平屋一部2階建","registered":"2020.08.17(令和2.08.17)","register_no":"07 － 0238","desc":"旧城下町の階段状敷地の下段に建ち、居間部と客間部を矩折れに接続し両棟から前庭を望む。客間は端正な意匠の書院で要所に黒柿や棕櫚などの銘木を用いる。居間部西寄り二階に配する座敷は埋れ木などの珍木も多用し、中国趣味を加味した独創的な意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013345"},{"id":"00013346","register_sub_id":"101","register_pk":"368434","name":"旧吉田家住宅紫雲閣","kana":"きゅうよしだけじゅうたくしうんかく","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県田村郡三春町字大町82","lat":37.44323333,"lng":140.48913333,"geo_status":"db","era":"明治28年頃","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積48㎡","structure_material":"土蔵造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"07 － 0239","desc":"主屋北西上段に建つ二階建の座敷蔵で、ベランダ風の下屋を矩折れに付す。二階座敷は軸部を赤色系の磯草模様に仕上げ、床柱と落掛に龍彫刻を巻き、鏡天井は円形に縁取り、赤漆で仕上げる。中国趣味を取入れ、多彩な工芸技術を駆使した、意匠奇抜で類稀な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013346"},{"id":"00009702","register_sub_id":"101","register_pk":"195531","name":"佐藤家住宅主屋","kana":"さとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県福島市泉字清水内3","lat":37.77786901,"lng":140.44429232,"geo_status":"db","era":"明治6","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"木造平屋一部2階建、茅葺、建築面積267㎡","structure_material":"木造平屋一部2階建","registered":"2013.12.24(平成25.12.24)","register_no":"07 － 0144","desc":"広い敷地の中央に南面して建つ。東面兜造西面入母屋造茅葺で、中央に越屋根を設ける。外壁は真壁で柱や貫を意匠的に現し、平面は東寄りに土間を、西に居室を並べ、広いブツマでは重厚な軸組をみせる。量感のある茅葺屋根がひときわ目をひく大型民家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009702"},{"id":"00009703","register_sub_id":"101","register_pk":"195532","name":"佐藤家住宅離れ","kana":"さとうけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県福島市泉字清水内3","lat":37.77789518,"lng":140.44409958,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積55㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"07 － 0145","desc":"主屋の西面北寄りに接続する東西棟。切妻造鉄板葺で、前後に下屋を設ける。トコと平書院を備えた八畳主室と六畳の次の間からなり、南面に廊下を通して主屋と文庫蔵を繋ぎ、北面には便所を設ける。主人の隠居用に増築された離れで、屋敷の変遷を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009703"},{"id":"00009704","register_sub_id":"101","register_pk":"195533","name":"佐藤家住宅文庫蔵","kana":"さとうけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県福島市泉字清水内3","lat":37.77786187,"lng":140.44402344,"geo_status":"db","era":"明治8","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積32㎡","structure_material":"土蔵造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"07 － 0146","desc":"主屋西方に離れを介して東西棟で建つ。土蔵造二階建、桁行六・六メートル梁間四・八メートル、切妻造、置屋根式の桟瓦葺で、東妻面を戸口とする。外壁漆喰塗で腰を洗出し仕上げとし、二階東面に土戸を開き、庇を付ける。屋敷西側の景観を整える土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009704"},{"id":"00009705","register_sub_id":"101","register_pk":"195534","name":"佐藤家住宅味噌蔵","kana":"さとうけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県福島市泉字清水内3","lat":37.77799036,"lng":140.44405199,"geo_status":"db","era":"明治6","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"07 － 0147","desc":"離れの北西側に東西棟で建つ。土蔵造二階建、桁行七・四メートル梁間四・七メートル、切妻造、置屋根式の鉄板葺で、東妻面南寄りを戸口として開戸を吊る。外壁漆喰塗で鉢巻を二段廻らし、腰を黒塗りとする。一階は土間で、旧家の暮らしぶりを伝える味噌蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009705"},{"id":"00000026","register_sub_id":"101","register_pk":"101016","name":"蛇の鼻御殿蔵座敷","kana":"じゃのはなごてんくらざしき","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県本宮市本宮字蛇の鼻38","lat":37.5140811,"lng":140.37632807,"geo_status":"db","era":"明治末","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末","structure":"木造2階建、鉄板葺、建築面積43㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"07 － 0006","desc":"土蔵造の建物で，内部を本館と同じく障壁画や銘木・巨木等の特殊な材料を用いた華やかな意匠で飾る。東北地方の邸宅でしばしばみられる土蔵の内部を座敷とする「蔵座敷」のひとつであり，なかでも内部が華やかな意匠をもつ優れたものとして注目できる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000026"},{"id":"00000025","register_sub_id":"101","register_pk":"101015","name":"蛇の鼻御殿本館","kana":"じゃのはなごてんほんかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県本宮市本宮字蛇の鼻38","lat":37.51395357,"lng":140.37609683,"geo_status":"db","era":"明治末","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末","structure":"木造2階建、鉄板葺、建築面積253㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"07 － 0005","desc":"８年の歳月をかけて建設されたと伝え，千鳥破風㎡唐破風を用いた外観，玄関の精緻な彫刻，内部の障壁画等に代表される華やかな意匠並びに各部に用いられた銘木・巨木等の材料に特徴がある。外観・内部ともに特異で類例が少ない建築物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000025"},{"id":"00012493","register_sub_id":"101","register_pk":"367788","name":"鈴木家住宅主屋","kana":"すずきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県南相馬市小高区仲町一丁目67","lat":37.564186,"lng":140.988235,"geo_status":"geocoded","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積85㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"07 － 0208","desc":"旧小高町中心部の街道沿いにある旧薬局主屋で、街道に北面する店舗背面に東面して建つ。切妻造の平屋建で正面北端に入母屋造の玄関を出す。内部は三室を並べ、東南二面に廊下を廻し、南端に控間と便所を設ける。浜通り北部の伝統商家の構成を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012493"},{"id":"00009700","register_sub_id":"101","register_pk":"195529","name":"瀬上嶋貫本家住宅表門","kana":"せのうえしまぬきほんけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県福島市瀬上町字本町90-8","lat":37.80238208,"lng":140.49074567,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造、瓦葺、間口2.3m、袖塀及び潜戸付","structure_material":"木造","registered":"2013.12.24(平成25.12.24)","register_no":"07 － 0142","desc":"敷地東面、主屋南側に構える。間口二・三メートルの薬医門、切妻造桟瓦葺で、両側に袖塀を付属し、北側に潜戸を開く。ケヤキの良材による普請で、几帳面取の本柱と控柱に各々冠木を渡し、梁を三筋架けて桁を受け、柱間に桟唐戸を開く。屋敷構えに風格を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009700"},{"id":"00009697","register_sub_id":"101","register_pk":"195526","name":"瀬上嶋貫本家住宅主屋","kana":"せのうえしまぬきほんけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県福島市瀬上町字本町90-2他","lat":37.8024637,"lng":140.49064145,"geo_status":"db","era":"明治32","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造2階建、鋼板葺、建築面積214㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"07 － 0139","desc":"造二階建、切妻造銅板葺である。奥州街道側の大きな妻面では、柱間に下見板を張り、破風拝みの飾りや窓庇などに洋風意匠を加味する。内部は上下階とも六間取系で一部を吹抜とする。神棚、座敷飾、欄間などの造作は上質で、二階洋間の内装も見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009697"},{"id":"00009698","register_sub_id":"101","register_pk":"195527","name":"瀬上嶋貫本家住宅離れ","kana":"せのうえしまぬきほんけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県福島市瀬上町字本町90-2他","lat":37.80256363,"lng":140.49059386,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、銅板葺、建築面積66㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"07 － 0140","desc":"主屋北面西寄りに南北棟で建ち、木造二階建、切妻造銅板葺である。上下階とも一〇畳二室を並べ、東面の縁にガラス戸をたてて庭を望む。一部の室内は緩く折上げた格天井を張り、座敷飾に黒柿などの銘木を多用して施工も優れ、豪奢な造作とする。気品のある離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009698"},{"id":"00009699","register_sub_id":"101","register_pk":"195528","name":"瀬上嶋貫本家住宅文庫蔵","kana":"せのうえしまぬきほんけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県福島市瀬上町字本町90-8","lat":37.802359,"lng":140.49063907,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積47㎡","structure_material":"土蔵造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"07 － 0141","desc":"表門南側に東西棟で建つ。土蔵造二階建、切妻造、置屋根式の桟瓦葺で、北面西寄りを戸口として下屋を設ける。外壁漆喰塗で腰を海鼠壁とし、二階東面に掛子塗の重厚な扉を吊り、鉢巻とともに黒漆喰塗として風格を備える。屋敷の正面構えを引立てる文庫蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009699"},{"id":"00009701","register_sub_id":"101","register_pk":"195530","name":"瀬上嶋貫本家住宅門及び土塀","kana":"せのうえしまぬきほんけじゅうたくもんおよびどべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県福島市瀬上町字本町90-4","lat":37.80255174,"lng":140.49076756,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"門 木造、瓦葺、間口1.9m 土塀 木造、瓦葺、総延長13m","structure_material":"門 木造","registered":"2013.12.24(平成25.12.24)","register_no":"07 － 0143","desc":"土塀は、主屋北面東端から道路沿いに矩折れにのびて庭を囲み、南寄りに腕木門を構える。切妻造桟瓦葺で、外側は腰に廻らした水切の下方の柱内を下見板張として主屋と意匠を揃え、上方は漆喰塗、また庭側は全面漆喰塗とする。屋敷の主庭周りの景観を整える門と塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009701"},{"id":"00008617","register_sub_id":"101","register_pk":"149338","name":"添田家住宅主屋","kana":"そえたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県石川郡石川町大字北山字羽貫田67","lat":37.167252,"lng":140.48437766,"geo_status":"db","era":"昭和8年／平成21年改修","year":1933,"year_source":"converted","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積117㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"07 － 0121","desc":"畑や木立に囲まれた山間の敷地中央後方に建つ。南北棟の東面中央に東西棟が付くＴ字型の構成になる。木造2階建で、南北棟は南北に各2室を配し、北室には座敷飾りを備える。その東に位置する15畳の中座敷は上部を吹抜けとする、開放感ある空間とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008617"},{"id":"00008620","register_sub_id":"101","register_pk":"149341","name":"添田家住宅醤油蔵","kana":"そえだけじゅうたくしょうゆぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県石川郡石川町大字北山字羽貫田67","lat":37.16705926,"lng":140.48455986,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、鉄板葺、建築面積49㎡","structure_material":"土蔵造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"07 － 0124","desc":"文庫蔵の南に平行して建つ。桁行9.1ｍ梁間5.3ｍ、土蔵造平屋建で、切妻造鉄板葺の置屋根。外壁は中塗仕上げとし、簡単な鉢巻をつくり、西妻面に出入口、南・東面に窓を穿つ。内部は等間隔に栗材の柱に荒壁とするなど、作業場らしい空間とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008620"},{"id":"00008619","register_sub_id":"101","register_pk":"149340","name":"添田家住宅西の蔵","kana":"そえだけじゅうたくにしのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県石川郡石川町大字北山字羽貫田67","lat":37.16732879,"lng":140.48410362,"geo_status":"db","era":"明治中期／昭和前期移築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積37㎡","structure_material":"土蔵造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"07 － 0123","desc":"主屋西方、敷地の西端に位置する。東西棟とする切妻造桟瓦葺の置屋根で、桁行8.2ｍ梁間4.5ｍの土蔵造二階建。内部は土間とし、和小屋を組む。切石基礎で、漆喰仕上げ、腰を海鼠壁とし、東面に出入口や窓を穿ち、上部に鏝細工の家紋を飾り、正面を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008619"},{"id":"00008618","register_sub_id":"101","register_pk":"149339","name":"添田家住宅文庫蔵","kana":"そえだけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県石川郡石川町大字北山字羽貫田67","lat":37.16714358,"lng":140.48462159,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"07 － 0122","desc":"主屋の東南に位置する。東西棟とする切妻造桟瓦葺の置屋根で、桁行6.4ｍ梁間3.6ｍの土蔵造二階建。西面に出入口を設け、下屋庇をかけ、身舎から側壁を続ける。漆喰壁で、腰を海鼠壁とし、鉢巻を黒漆喰で仕上げ、まとまりのある重厚な外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008618"},{"id":"00011857","register_sub_id":"101","register_pk":"211045","name":"髙島家住宅コンクリート蔵","kana":"たかしまけじゅうたくこんくりーとくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県南相馬市小高区上町一丁目87","lat":37.565115,"lng":140.983761,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"鉄筋コンクリート造2階建、建築面積37㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"07-181","desc":"鉄筋コンクリート造の蔵座敷。一階を倉庫とし、二階は壁・天井を洋風漆喰塗意匠でまとめる座敷とする。壁面上部に洋風の持送りを設け、装飾豊かなパラペットで囲まれる屋上を張出す外観が特徴。屋上に上がる外階段の踊場が入口の蔵前庇を兼ねる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011857"},{"id":"00011858","register_sub_id":"101","register_pk":"211046","name":"髙島家住宅門及び塀","kana":"たかしまけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県南相馬市小高区上町一丁目87","lat":37.564928,"lng":140.983863,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"門 煉瓦造 間口2.8m 塀 煉瓦造、総延長34m","structure_material":"門 煉瓦造 間口2.8m 塀 煉瓦造","registered":"2017.10.27(平成29.10.27)","register_no":"07-182","desc":"コンクリート蔵の南西端から敷地南端で鋭角に折り返し敷地東面の途中まで延びる塀と、街路よ寄りやや南方に位置する門。塀は半枚厚の煉瓦造で、上部は煉瓦を抜いて表情を変える。門柱は塀よりも高く伸ばし、上部を張出す。地域の歴史的景観を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011858"},{"id":"00012688","register_sub_id":"101","register_pk":"367591","name":"野口英世生家主屋","kana":"のぐちひでよせいかしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県耶麻郡猪苗代町大字三ツ和字前田139","lat":37.536815,"lng":140.07323194,"geo_status":"db","era":"文政6年（1823）／昭和56年改修","year":1823,"year_source":"db","year_min":1823,"year_max":1823,"year_label":null,"structure":"木造平屋建、茅葺、建築面積131㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"07 － 209","desc":"細菌学者･野口英世の生家。猪苗代湖畔に南面して建つ農家主屋で、寄棟造茅葺、東側土間部の前面を張出し、屋根を葺下ろす。内部は馬屋のある土間と囲炉裏のある広間、奥の座敷と納戸からなる。建築年代が明らかで、会津地方の伝統形式の指標となる民家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012688"},{"id":"00000939","register_sub_id":"101","register_pk":"101929","name":"林家住宅","kana":"はやしけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"昭和前","pref":"福島県","address":"福島県会津若松市材木町1-9-25","lat":37.48915804,"lng":139.91176728,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造２階建，瓦葺，建築面積382㎡","structure_material":"木造２階建","registered":"1998.12.11(平成10.12.11)","register_no":"07 － 0024","desc":"２階建の大型の和風住宅で，切妻屋根の連なる重厚な構えとなる。玄関左手に洋間を設け，２階は１５畳大の客室３室が連なるなど昭和初期の大規模邸宅の構えを保つ。東山温泉のもとの原瀧本館を手がけた越後の坂田棟梁が建てたと伝える質の高い住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000939"},{"id":"00002202","register_sub_id":"101","register_pk":"103192","name":"針生館北土蔵","kana":"はりゅうかんきたどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県南会津郡南会津町針生字鳥井戸1201","lat":37.18797682,"lng":139.66117468,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"07 － 0053","desc":"主屋の西方に位置する桁行４間，梁行２間半規模，切妻造，置屋根形式の２階建土蔵で，東妻に庇を出して蔵前を造る。棟木墨書には「修築」とあり，前身土蔵に大幅な改造が加えられたと見られる。家人から「新しい蔵」と呼ばれ，西妻面の開口も大きめに造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002202"},{"id":"00002201","register_sub_id":"101","register_pk":"103191","name":"針生館主屋","kana":"はりゅうかんしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県南会津郡南会津町針生字鳥井戸1201","lat":37.18797024,"lng":139.66129111,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、鉄板葺、建築面積232㎡","structure_material":"木造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"07 － 0052","desc":"田島町から西に約１８ｋｍ，国道２８９号沿いに位置する。現当主の祖父の時代に建設と伝える。Ｌ型平面の曲屋風大型民家で，南面して建つ。寄棟造であるが，南妻を切り落として兜造風にみせている点に特徴がある。茅葺を保ち，民宿として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002201"},{"id":"00002203","register_sub_id":"101","register_pk":"103193","name":"針生館南土蔵","kana":"はりゅうかんみなみどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県南会津郡南会津町針生字鳥井戸1201","lat":37.1878374,"lng":139.66123589,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"07 － 0054","desc":"主屋の南西方，北土蔵の南方に位置する。北土蔵と同一規模で桁行４間，梁行２間半とし，屋根も同様に置屋根形式に造り，腰には押縁下見を張る。家人からは「いい蔵」と呼ばれ，東妻面上部に施主平野新作の「新」を付ける。大工は地元の星兼松ら。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002203"},{"id":"00012479","register_sub_id":"101","register_pk":"367774","name":"平田家住宅主屋","kana":"ひらたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県会津若松市行仁町154","lat":37.497246,"lng":139.937515,"geo_status":"geocoded","era":"明治後期／大正後期･昭和30年代･同50年代改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、金属板葺、建築面積124㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"07 － 0194","desc":"若松城下の旧武家地にある住宅で、主屋は南が街路に面した敷地中央に建つ。寄棟造の平屋建で、東西棟の居室部と東に接続する南北棟の座敷からなる。居室部は南面に切妻造の玄関を出し、その奥に和洋折衷の応接間を設ける。城下町の近代の展開を示す和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012479"},{"id":"00012481","register_sub_id":"101","register_pk":"367776","name":"平田家住宅西蔵","kana":"ひらたけじゅうたくにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県会津若松市行仁町154","lat":37.497246,"lng":139.937515,"geo_status":"geocoded","era":"明治8年／昭和30年代改修","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積62㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"07 － 0196","desc":"主屋背面の西端に接続する蔵座敷。土蔵造二階建、南北棟の切妻造で、南面中央に扉口を開き、内部は一階に二室の続き間を設ける。東南北三面に下屋を廻し、正面を蔵前とし、側背面に縁を廻す。旧城下に残る最古級の建物で、近代初頭の武家地の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012481"},{"id":"00012480","register_sub_id":"101","register_pk":"367775","name":"平田家住宅東蔵","kana":"ひらたけじゅうたくひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県会津若松市行仁町154","lat":37.497246,"lng":139.937515,"geo_status":"geocoded","era":"明治33年","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"07 － 0195","desc":"主屋正面の東端に接続し、敷地東南隅にあって街路に面して建つ。土蔵造二階建、南北棟の切妻造で和小屋とし、北面中央に扉口を開く。内部は上下階とも板敷で、家財道具を収納する。伝統形式を継承した蔵で、武家地から発展した近代住宅地の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012480"},{"id":"00015276","register_sub_id":"101","register_pk":"532400","name":"古川家住宅穀蔵","kana":"ふるかわけじゅうたくこくぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県会津若松市柳原町一丁目370","lat":37.49396111,"lng":139.9064,"geo_status":"db","era":"大正6年／昭和30年・同62年改修","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"土蔵2階建、瓦葺、建築面積77㎡","structure_material":"土蔵2階建","registered":"2025.03.13(令和7.03.13)","register_no":"07 - 0287","desc":"銀山街道沿いに所在する旧米穀商の穀物蔵。二階建切妻造平入桟瓦葺。外壁は漆喰塗で軒まで塗込め、腰はモルタル塗仕上。1階北は土間で米の貯蔵場、南を床上とし、二階はかつての穀蔵。上部に束立の和小屋を現す。戸口や窓に掛子塗扉を吊る重厚な外観の穀蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015276"},{"id":"00015277","register_sub_id":"101","register_pk":"532401","name":"古川家住宅座敷蔵","kana":"ふるかわけじゅうたくざしきぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県会津若松市柳原町一丁目370","lat":37.49379722,"lng":139.90644167,"geo_status":"db","era":"大正7年／昭和62年改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"土蔵2階建、瓦葺、建築面積66㎡","structure_material":"土蔵2階建","registered":"2025.03.13(令和7.03.13)","register_no":"07 - 0288","desc":"穀物蔵の南東に位置する座敷蔵。二階建切妻造桟瓦葺で軒まで漆喰で塗込める。小屋組はキングポスト・トラス。二階南室は南庭に面して窓を開けた床構え付き座敷で、黒柿の床柱など良材を用い、繊細な組子のガラス障子を建てた付書院など良質なつくりの座敷蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015277"},{"id":"00011252","register_sub_id":"101","register_pk":"209087","name":"瓶子家住宅氏神社","kana":"へいしけじゅうたくうじがみしゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県福島市森合字台35-1","lat":37.766603,"lng":140.456293,"geo_status":"db","era":"明治21／昭和59移築","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造平屋建、板葺、2棟よりなる、建築面積0.34㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"07－0174","desc":"敷地北西、穀蔵の南に東面して建つ。石積基壇を共有する二棟の小社からなり、南が大地主神、北が三十三観世音を祀る。南が一間社切妻造庇付、北が一間社切妻造で唐破風の向拝を付し、屋根はいずれも板葺である。丁寧な作りの小社で、屋敷地の景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011252"},{"id":"00011250","register_sub_id":"101","register_pk":"209085","name":"瓶子家住宅穀蔵","kana":"へいしけじゅうたくこくぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県福島市森合字台35-1","lat":37.76664,"lng":140.456311,"geo_status":"db","era":"昭和前期／昭和59移築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積10㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"07－0172","desc":"敷地北西隅に建つ。桁行五・五メートル、梁間一・九メートル、切妻造桟瓦葺の板蔵で、柱を一尺半置きに立て間に横板を建て込む。平面は南から半間、一間、半間、一間に区画され、半間室の東面は間柱を取り外し出入口となる。豪農の屋敷構えを伝える穀蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011250"},{"id":"00011247","register_sub_id":"101","register_pk":"209082","name":"瓶子家住宅主屋","kana":"へいしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県福島市森合字台35-1","lat":37.766345,"lng":140.456388,"geo_status":"db","era":"明治前期／昭和前期改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、鉄板葺、建築面積346㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"07－0169","desc":"福島市街地の北部に位置する屋敷の主屋で、敷地中心に建つ。桁行一三間、梁間六間と大規模な木造二階建、入母屋造鉄板葺平入で、大棟に越屋根を付す。内部は床上部を含めほぼ天井を張らず、梁には蚕棚を架けていた跡が残る。地域に残る希少な大規模農家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011247"},{"id":"00011251","register_sub_id":"101","register_pk":"209086","name":"瓶子家住宅長屋門","kana":"へいしけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県福島市森合字台35-1","lat":37.766165,"lng":140.456351,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積86㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"07－0173","desc":"敷地南に建つ。桁行七間半、梁間三間、切妻造、桟瓦葺で、外壁は腰を下見板張とする他は柱、貫を現しとした真壁漆喰塗仕上とする。平面は中央に門口を開き、上部を竪格子とした両開板戸を吊る。門口の東を牛小屋、西を物置とする。屋敷の表構えを飾る長屋門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011251"},{"id":"00011248","register_sub_id":"101","register_pk":"209083","name":"瓶子家住宅離れ","kana":"へいしけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県福島市森合字台35-1","lat":37.766479,"lng":140.456477,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階建、鉄板葺、建築面積71㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"07－0170","desc":"主屋の背面に建ち、主屋と渡廊下で接続する。木造二階建で、屋根は寄棟造鉄板葺とする。内部は一階、二階とも六畳を二室並べ、東西に階段、南北に廊下を付す。二階座敷は床、棚、付書院を設えヤシやケヤキなどの銘木を用いるなど上質な座敷である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011248"},{"id":"00011249","register_sub_id":"101","register_pk":"209084","name":"瓶子家住宅文庫蔵","kana":"へいしけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県福島市森合字台35-1","lat":37.766547,"lng":140.456394,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積55㎡","structure_material":"土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"07－0171","desc":"離れの西隣に並び建つ。土蔵造、二階建、切妻造瓦棒鉄板葺で南面東半に戸前を下屋として附属する。外観は一階部分に煉瓦を長手積で張る他は漆喰塗とし、一階南面と二階両妻面に窓を開く。内部は板床で、壁は横板張とし、一部畳敷の畳寄と部屋境の欄間を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011249"},{"id":"00000520","register_sub_id":"101","register_pk":"101510","name":"細井家住宅酒蔵","kana":"ほそいけじゅうたくさかぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県南会津郡南会津町静川字風下甲175","lat":37.19785502,"lng":139.6853996,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造２階建，鉄板葺，建築面積93㎡","structure_material":"土蔵造２階建","registered":"1998.04.21(平成10.04.21)","register_no":"07 － 0018","desc":"主屋の北東に建つ妻入の土蔵。当家が正式に酒造業を営み始めた寛政２年(1790)を大きく降らない頃の建築と考えられる。江戸時代後期以降には，有力な大規模農家が様々な業務を展開するようになるが，その様子を物語る建物のひとつである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000520"},{"id":"00000515","register_sub_id":"101","register_pk":"101505","name":"細井家住宅主屋","kana":"ほそいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県南会津郡南会津町静川字風下甲175","lat":37.19780142,"lng":139.68534146,"geo_status":"db","era":"万延2","year":1861,"year_source":"db","year_min":1861,"year_max":1861,"year_label":null,"structure":"木造平屋建，茅葺，建築面積246㎡","structure_material":"木造平屋建","registered":"1998.04.21(平成10.04.21)","register_no":"07 － 0013","desc":"江戸時代後期に村名主を勤めた家で，町内きっての旧家として知られる大規模農家。開放的な外観，部屋境に差鴨居を多用すること，軒が比較的に低いこと等に時代の特徴があらわれている。現在直屋だが，もとは土間側に馬屋中門が取り付いていた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000515"}];
